local _, RM = ...
if RM.LOCALE ~= "itIT" then return end
local L = RM.L

L["Ruinen von Ahn'Qiraj"] = "Rovine di Ahn'Qiraj"
L["Kurinnaxx"] = "Kurinnaxx"
L["- Tödliche Wunde: stapelnder Debuff auf dem Tank, reduziert erhaltene Heilung -> Tankwechsel bei hohen Stapeln."] = "- Ferita Mortale: debuff a stack sul tank, riduce le cure ricevute -> cambio tank con stack alti."
L["- Sandfalle: erscheint unter einem Spieler und lässt ihn bei Auslösen verfehlen -> sofort herauslaufen."] = "- Trappola di Sabbia: appare sotto un giocatore e lo fa mancare quando si attiva -> uscirne subito."
L["- Raserei bei ca. 30 %: deutlich mehr Schaden -> Heiler auf die Tanks, Schaden hochfahren."] = "- Frenesia a circa 30 %: molto più danno -> healer sui tank, alzare il DPS."
L["Taktik: Zwei Tanks wechseln sich ab, Raid verteilt hinter dem Boss, Sandfallen sofort verlassen."] = "Tattica: Due tank si alternano, raid sparso dietro al boss, uscire subito dalle Trappole di Sabbia."
L["KURINNAXX: Tankwechsel bei Tödlicher Wunde! Raus aus der Sandfalle!"] = "KURINNAXX: Cambio tank su Ferita Mortale! Fuori dalla Trappola di Sabbia!"
L["Ab 30 % Raserei: Heiler auf die Tanks, alles auf den Boss."] = "Dal 30 % Frenesia: healer sui tank, tutti sul boss."
L["General Rajaxx + Wellen der Qiraji (mit Generalleutnant Andorov)"] = "Generale Rajaxx + ondate di Qiraji (con il Tenente Generale Andorov)"
L["- Wellen: mehrere Wellen Qiraji-Krieger mit je einem Hauptmann greifen nacheinander an -> Hauptmann und Adds sauber abarbeiten."] = "- Ondate: più ondate di guerrieri Qiraji, ognuna con un capitano, attaccano una dopo l'altra -> pulire bene capitano e add."
L["- Andorov: NPC-Verbündeter mit Aura und Händler -> am Leben halten, er hilft bei den Wellen."] = "- Andorov: PNG alleato con aura e mercante -> tenerlo in vita, aiuta con le ondate."
L["- Donnerkrachen (Rajaxx): halbiert das aktuelle Leben aller Spieler in der Nähe -> Raid hoch halten, Abstand für Fernkampf."] = "- Fragore del Tuono (Rajaxx): dimezza la vita attuale di tutti i giocatori vicini -> raid sempre su di vita, ranged a distanza."
L["- Entwaffnen/Ansturm-Fähigkeiten der Hauptleute: Tankschaden schwankt -> Heiler aufmerksam."] = "- Disarmo/Carica dei capitani: il danno sul tank oscilla -> healer attenti."
L["Taktik: Wellen am Startpunkt tanken und mit Flächenschaden töten, zwischen den Wellen regenerieren. Zum Schluss Rajaxx tanken und mit allem töten."] = "Tattica: Tankare le ondate al punto di partenza e ucciderle ad AoE, rigenerare tra un'ondata e l'altra. Alla fine tankare Rajaxx e ucciderlo con tutto."
L["RAJAXX: Wellen sauber abarbeiten, Andorov am Leben halten!"] = "RAJAXX: Pulire bene le ondate, tenere in vita Andorov!"
L["Donnerkrachen halbiert Leben: Raid immer voll heilen."] = "Fragore del Tuono dimezza la vita: raid sempre full."
L["Moam + Manadämonen"] = "Moam + Demoni di Mana"
L["- Mana entziehen: Moam saugt Mana der Spieler; bei vollem Mana Arkanausbruch auf den ganzen Raid -> sein Mana leer halten (Mana verbrennen, Vipernbiss, Mana entziehen)."] = "- Risucchio di Mana: Moam assorbe il mana dei giocatori; a mana pieno Esplosione Arcana su tutto il raid -> tenere il suo mana a zero (Bruciamana, Puntura di Vipera, Risucchio di Mana)."
L["- Versteinern: Moam wird zu Stein und ruft Manadämonen -> Dämonen verbannen bzw. tanken und töten."] = "- Pietrificazione: Moam diventa di pietra ed evoca Demoni di Mana -> esiliare i demoni o tankarli e ucciderli."
L["- Manadämonen: Arkanschaden und Spalten -> nicht frei laufen lassen."] = "- Demoni di Mana: danno arcano e fendente -> non lasciarli liberi."
L["Taktik: Schnell Schaden machen, Jäger/Priester/Hexer halten sein Mana unten. Bei Versteinerung Hexer auf die Manadämonen einteilen."] = "Tattica: Fare danno in fretta, Cacciatori/Sacerdoti/Stregoni tengono basso il suo mana. Durante la pietrificazione assegnare gli Stregoni ai Demoni di Mana."
L["MOAM: Sein Mana leer halten! Bei Stein: Manadämonen verbannen!"] = "MOAM: Tenere il suo mana a zero! In pietra: esiliare i Demoni di Mana!"
L["Jäger Vipernbiss, Priester Mana verbrennen, Hexer Mana entziehen."] = "Cacciatori Puntura di Vipera, Sacerdoti Bruciamana, Stregoni Risucchio di Mana."
L["Moam (Dämonen)"] = "Moam (demoni)"
L["Jeder Manadämon ein Symbol, je ein Hexer verbannt sein zugewiesenes Symbol."] = "Ogni Demone di Mana un simbolo, ogni Stregone esilia il simbolo assegnato."
L["Buru der Verschlinger + Eier"] = "Buru l'Ingordo + uova"
L["- Fixieren: Buru verfolgt einen zufälligen Spieler -> diesen Spieler Buru in ein Ei ziehen lassen."] = "- Fissazione: Buru insegue un giocatore a caso -> quel giocatore porta Buru contro un uovo."
L["- Eier: zerstörte Eier explodieren und verletzen Buru (und Spieler in der Nähe), es schlüpfen Brutlinge -> Eier nur zerschlagen, wenn Buru danebensteht, Abstand halten."] = "- Uova: le uova distrutte esplodono e feriscono Buru (e i giocatori vicini), escono dei piccoli -> rompere le uova solo quando Buru è accanto, tenere la distanza."
L["- Phase 2 (ca. 20 %): Buru verliert Panzer, kriechende Seuche verursacht steigenden Raidschaden -> alles auf den Boss."] = "- Fase 2 (circa 20 %): Buru perde la corazza, la piaga strisciante causa danno crescente al raid -> tutti sul boss."
L["Taktik: Raid zerschlägt Eier gezielt, wenn Buru den fixierten Spieler durch ein Ei verfolgt; Brutlinge schnell töten. Ab 20 % voller Schaden."] = "Tattica: Il raid rompe le uova quando Buru insegue il giocatore fissato attraverso un uovo; uccidere subito i piccoli. Dal 20 % danno pieno."
L["BURU: Fixierten Spieler -> Buru durch die Eier ziehen! Abstand zur Explosion!"] = "BURU: Giocatore fissato -> portare Buru sulle uova! Distanza dall'esplosione!"
L["Bei 20 % alles auf Buru, Heiler Raid hoch halten."] = "Al 20 % tutti su Buru, healer tengono su il raid."
L["Ayamiss der Jäger + Larven/Wespen"] = "Ayamiss la Cacciatrice + larve/vespe"
L["- Phase 1 in der Luft: nur Fernkampf erreicht sie -> Fernkampf auf den Boss, Nahkampf auf Adds."] = "- Fase 1 in volo: solo i ranged la raggiungono -> ranged sul boss, melee sugli add."
L["- Lähmen: ein Spieler wird auf den Altar gebracht, eine Larve läuft hin -> Larve sofort töten, sonst stirbt der Spieler."] = "- Paralisi: un giocatore viene portato sull'altare, una larva ci corre -> uccidere subito la larva, altrimenti il giocatore muore."
L["- Giftstachelsalve: Naturschaden auf viele Spieler -> Gift entfernen, Naturwiderstand hilft."] = "- Raffica di Pungiglioni Velenosi: danno da natura su molti giocatori -> rimuovere il veleno, la resistenza alla natura aiuta."
L["- Phase 2 (ca. 70 %): landet und wird getankt, ruft weiter Wespen -> Tank übernimmt, Adds mit Flächenschaden töten."] = "- Fase 2 (circa 70 %): atterra e viene tankata, continua a evocare vespe -> il tank la prende, add uccisi ad AoE."
L["Taktik: Fernkampf schießt den Boss herunter, Nahkampf kümmert sich um Larven und Wespen. Nach der Landung normal tanken."] = "Tattica: I ranged abbattono il boss, i melee si occupano di larve e vespe. Dopo l'atterraggio tank normale."
L["AYAMISS: Larve zum Altar sofort töten! Fernkampf auf den Boss!"] = "AYAMISS: Uccidere subito la larva diretta all'altare! Ranged sul boss!"
L["Gift entfernen. Ab 70 % landet sie: Tank bereit."] = "Rimuovere il veleno. Dal 70 % atterra: tank pronto."
L["Ossirian der Narbenlose"] = "Ossirian l'Intatto"
L["- Stärke des Ossirian: ohne Schwäche fast unverwundbar und tödlich -> immer zu einem Kristall ziehen."] = "- Forza di Ossirian: senza debolezza è quasi invulnerabile e letale -> portarlo sempre verso un cristallo."
L["- Kristalle: Aktivieren gibt ihm eine Zauberschwäche für ca. 45 Sek. -> rechtzeitig nächsten Kristall aktivieren und Boss dorthin tanken."] = "- Cristalli: attivarli gli dà una debolezza a una scuola per circa 45 sec. -> attivare in tempo il cristallo successivo e tankare il boss lì."
L["- Wirbelstürme: wandern durch den Raum -> ausweichen."] = "- Tornado: si muovono per la stanza -> schivarli."
L["- Fluch der Sprachen/Umhüllende Winde/Kriegsdonner: Raidkontrolle -> entfluchen, Abstand halten."] = "- Maledizione delle Lingue/Venti Avvolgenti/Tuono di Guerra: controllo sul raid -> rimuovere le maledizioni, tenere la distanza."
L["Taktik: Tank kitet Ossirian von Kristall zu Kristall, ein Spieler aktiviert den nächsten vor Ablauf der Schwäche. Schaden passend zur Schwäche-Schule."] = "Tattica: Il tank kita Ossirian da cristallo a cristallo, un giocatore attiva il successivo prima che scada la debolezza. Danno adatto alla scuola della debolezza."
L["OSSIRIAN: Nächsten Kristall rechtzeitig aktivieren! Schwäche nie ablaufen lassen!"] = "OSSIRIAN: Attivare in tempo il prossimo cristallo! Mai far scadere la debolezza!"
L["Wirbelstürmen ausweichen, Flüche entfernen."] = "Schivare i tornado, rimuovere le maledizioni."
L["Tempel von Ahn'Qiraj"] = "Tempio di Ahn'Qiraj"
L["Der Prophet Skeram + 2 Abbilder"] = "Il Profeta Skeram + 2 immagini"
L["- Arkane Explosion: hoher Flächenschaden -> unterbrechen, Nahkampf vorsichtig."] = "- Esplosione Arcana: forte danno ad area -> kickare, melee attenti."
L["- Wahre Erfüllung: Gedankenkontrolle -> Spieler kontrollieren (Verwandlung, Furcht), nicht töten."] = "- Vero Compimento: controllo mentale -> controllare i giocatori (Metamorfosi, Paura), non ucciderli."
L["- Teleport: Skeram springt auf eine andere Plattform und setzt die Bedrohung zurück -> auf jeder Plattform ein Tank."] = "- Teletrasporto: Skeram salta su un'altra piattaforma e azzera l'aggro -> un tank su ogni piattaforma."
L["- Abbilder bei 75/50/25 %: zwei Kopien erscheinen -> Kopien tanken, echten Skeram finden und töten."] = "- Immagini al 75/50/25 %: compaiono due copie -> tankare le copie, trovare e uccidere il vero Skeram."
L["Taktik: Drei Tanks auf drei Positionen verteilen, Unterbrecher fest einteilen. Bei Abbildern echten Skeram markieren und zuerst töten."] = "Tattica: Tre tank su tre posizioni, kicker assegnati fissi. Con le immagini marcare il vero Skeram e ucciderlo per primo."
L["SKERAM: Arkane Explosion unterbrechen! Gedankenkontrolle kontrollieren, nicht töten!"] = "SKERAM: Kickare Esplosione Arcana! Controllare i mind control, non ucciderli!"
L["Bei Abbildern nur auf den echten Skeram (Totenkopf)."] = "Con le immagini solo sul vero Skeram (teschio)."
L["Skeram"] = "Skeram"
L["Totenkopf auf den echten Skeram, Kreuz und Viereck auf die Abbilder."] = "Teschio sul vero Skeram, croce e quadrato sulle immagini."
L["Adel der Silithiden: Lord Kri, Prinzessin Yauj, Vem"] = "Reali dei Silitidi: Lord Kri, Principessa Yauj, Vem"
L["- Lord Kri: Giftwolke und bei Tod eine Giftwolke -> nicht darin stehen, Gift entfernen."] = "- Lord Kri: nube tossica, e una nube tossica alla morte -> non starci dentro, rimuovere il veleno."
L["- Prinzessin Yauj: Große Heilung und Furcht -> Heilung unterbrechen, Furcht beachten; bei Tod erscheinen Käfer -> Flächenschaden."] = "- Principessa Yauj: Cura Superiore e paura -> kickare la cura, attenzione alla paura; alla morte escono scarabei -> AoE."
L["- Vem: Ansturm und Rückstoß, wird stärker, wenn die anderen sterben -> stabil tanken."] = "- Vem: carica e respinta, diventa più forte quando muoiono gli altri -> tank stabile."
L["- Wer zuletzt stirbt, bestimmt die Beute -> Reihenfolge vorher absprechen."] = "- Chi muore per ultimo determina il loot -> concordare prima l'ordine."
L["Taktik: Alle drei getrennt tanken, Unterbrecher auf Yauj, Kill-Reihenfolge nach Absprache (der letzte Boss bestimmt die Beute)."] = "Tattica: Tankare tutti e tre separati, kicker su Yauj, ordine di kill concordato (l'ultimo boss determina il loot)."
L["SILITHIDEN: Kill-Reihenfolge laut Symbolen! Yauj-Heilung unterbrechen!"] = "SILITIDI: Ordine di kill secondo i simboli! Kickare la cura di Yauj!"
L["Giftwolken meiden. Käfer nach Yauj mit Flächenschaden töten."] = "Evitare le nubi tossiche. Dopo Yauj uccidere gli scarabei ad AoE."
L["Adel der Silithiden"] = "Reali dei Silitidi"
L["Totenkopf zuerst, dann Kreuz, Viereck zuletzt (bestimmt die Beute)."] = "Prima il teschio, poi la croce, il quadrato per ultimo (determina il loot)."
L["Schlachtwache Sartura + 3 Königliche Wachen"] = "Guardia da Battaglia Sartura + 3 Guardie Reali"
L["- Wirbelwind: Sartura und Wachen wirbeln und laufen durch den Raid -> Abstand halten, Nahkampf raus."] = "- Turbine: Sartura e le guardie roteano e corrono nel raid -> tenere la distanza, melee fuori."
L["- Wachen: verursachen viel Schaden -> mit Betäubungsrotation kontrollieren und zuerst töten."] = "- Guardie: fanno molto danno -> controllarle con una rotazione di stun e ucciderle per prime."
L["- Wutanfall bei ca. 20 % und hartes Zeitlimit -> zügig Schaden machen."] = "- Ira a circa 20 % e enrage a tempo rigido -> fare danno in fretta."
L["Taktik: Wachen einzeln tanken und nacheinander töten, Betäubungen fest einteilen. Danach Sartura, Raid verteilt."] = "Tattica: Tankare le guardie singolarmente e ucciderle una alla volta, stun assegnati fissi. Poi Sartura, raid sparso."
L["SARTURA: Wachen zuerst! Betäubungen rotieren, bei Wirbelwind weg!"] = "SARTURA: Prima le guardie! Ruotare gli stun, via durante il Turbine!"
L["Raid verteilt stehen. Ab 20 % Wutanfall: Heiler auf Tank."] = "Raid sparso. Dal 20 % Ira: healer sul tank."
L["Sartura"] = "Sartura"
L["Totenkopf, Kreuz, Viereck auf die drei Wachen in Tötungsreihenfolge."] = "Teschio, croce, quadrato sulle tre guardie in ordine di kill."
L["Fankriss der Unnachgiebige + Brut/Jungtiere"] = "Fankriss l'Inflessibile + covata/piccoli"
L["- Tödliche Wunde: stapelnder Heilungsreduktions-Debuff -> Tankwechsel."] = "- Ferita Mortale: debuff a stack che riduce le cure -> cambio tank."
L["- Brut des Fankriss: wird nach kurzer Zeit wütend -> sofort töten."] = "- Covata di Fankriss: dopo poco va in frenesia -> uccidere subito."
L["- Vekniss-Jungtiere: kommen aus den Tunneln -> Offtank sammelt sie, Flächenschaden."] = "- Piccoli di Vekniss: escono dai tunnel -> l'offtank li raccoglie, AoE."
L["- Umschlingen: Spieler werden in die Tunnel versetzt -> zurücklaufen, Adds dort nicht ignorieren."] = "- Avvinghiamento: i giocatori vengono spostati nei tunnel -> tornare indietro, non ignorare gli add lì."
L["Taktik: Zwei bis drei Tanks wechseln auf dem Boss, Fernkampf tötet Brut sofort. Schnell Schaden machen, bevor Adds überhandnehmen."] = "Tattica: Due o tre tank si alternano sul boss, i ranged uccidono subito la covata. Fare danno in fretta prima che gli add prendano il sopravvento."
L["FANKRISS: Brut sofort töten! Tankwechsel bei Tödlicher Wunde!"] = "FANKRISS: Uccidere subito la covata! Cambio tank su Ferita Mortale!"
L["Jungtiere zum Offtank, Flächenschaden."] = "Piccoli all'offtank, AoE."
L["Viscidus"] = "Viscidus"
L["- Gefrieren: Viscidus muss mit Frostschaden eingefroren werden (Frostblitz, Frost-Zauberstäbe, Frostöl) -> alle Frostschaden."] = "- Congelamento: Viscidus va congelato con danno da gelo (Dardo di Gelo, bacchette del gelo, olio del gelo) -> tutti danno da gelo."
L["- Zerschlagen: eingefroren mit Nahkampf zerschlagen -> er zerfällt in Kugeln."] = "- Frantumare: da congelato va frantumato dai melee -> si divide in globi."
L["- Kugeln: laufen zur Mitte zurück und heilen ihn -> alle Kugeln töten."] = "- Globi: tornano al centro e lo curano -> uccidere tutti i globi."
L["- Giftblitzsalve und Giftwolken: Naturschaden -> Naturwiderstand, Gift entfernen."] = "- Raffica di Dardi Velenosi e nubi tossiche: danno da natura -> resistenza alla natura, rimuovere il veleno."
L["Taktik: Frost-Phase mit allem Fernkampf, Zerschlagen mit Nahkampf, danach Kugeln mit Flächenschaden. Wiederholen bis er tot ist."] = "Tattica: Fase gelo con tutti i ranged, frantumare con i melee, poi globi ad AoE. Ripetere finché muore."
L["VISCIDUS: Alles Frostschaden! Gefroren -> Nahkampf zerschlagen!"] = "VISCIDUS: Tutti danno da gelo! Congelato -> melee frantumano!"
L["Alle Kugeln töten, bevor sie die Mitte erreichen."] = "Uccidere tutti i globi prima che raggiungano il centro."
L["Prinzessin Huhuran"] = "Principessa Huhuran"
L["- Raserei: deutlich mehr Schaden -> Jäger mit Einlullender Schuss sofort entfernen."] = "- Frenesia: molto più danno -> Cacciatori la rimuovono subito con Tiro Tranquillizzante."
L["- Wyverngift: Schlaf auf Spielern, beim Bannen Schaden -> gezielt bannen."] = "- Veleno di Viverna: sonno sui giocatori, al dispel fa danno -> dispellare in modo mirato."
L["- Giftblitzsalve: trifft die nächsten Spieler -> Naturwiderstand-Gruppe nahe am Boss."] = "- Raffica di Dardi Velenosi: colpisce i giocatori più vicini -> gruppo con resistenza alla natura vicino al boss."
L["- Säurespucke: Stapel-Debuff auf Tank; ab 30 % Berserker -> Burn-Phase, Heiler voll."] = "- Sputo Acido: debuff a stack sul tank; dal 30 % berserk -> fase burn, healer al massimo."
L["Taktik: Naturwiderstand bei Nahkampf und Tank, Jäger-Rotation für Einlullender Schuss. Ab 30 % alles zünden und Raid hoch halten."] = "Tattica: Resistenza alla natura su melee e tank, rotazione dei Cacciatori per Tiro Tranquillizzante. Dal 30 % tutti i CD e raid sempre su."
L["HUHURAN: Raserei sofort einlullen! Ab 30 % Burn!"] = "HUHURAN: Frenesia subito tranquillizzata! Dal 30 % burn!"
L["Naturwiderstand nahe am Boss, Wyverngift gezielt bannen."] = "Resistenza alla natura vicino al boss, dispellare il Veleno di Viverna in modo mirato."
L["Zwillingsimperatoren: Vek'lor + Vek'nilash"] = "Imperatori Gemelli: Vek'lor + Vek'nilash"
L["- Vek'lor: immun gegen körperlichen Schaden, Schattenblitz, Blizzard, Arkane Explosion -> von einem Hexer (Schattenschutz) getankt."] = "- Vek'lor: immune al danno fisico, Dardo d'Ombra, Blizzard, Esplosione Arcana -> tankato da uno Stregone (protezione dall'ombra)."
L["- Vek'nilash: immun gegen Magie, Aufwärtshaken -> von Kriegern getankt, nur Nahkampf."] = "- Vek'nilash: immune alla magia, Montante -> tankato dai Guerrieri, solo melee."
L["- Bruder heilen: sind sie nah beieinander, heilen sie sich -> immer weit auseinander halten."] = "- Cura Fratello: se sono vicini si curano a vicenda -> tenerli sempre ben separati."
L["- Teleport: tauschen regelmäßig die Plätze -> Tanks an beiden Seiten bereit, Bedrohung neu aufbauen; Käfer explodieren/mutieren -> töten."] = "- Teletrasporto: si scambiano regolarmente di posto -> tank pronti su entrambi i lati, ricostruire l'aggro; gli insetti esplodono/mutano -> ucciderli."
L["Taktik: Zwei Tankgruppen an beiden Enden, Hexer auf Vek'lor, Krieger auf Vek'nilash. Nach jedem Teleport sofort übernehmen."] = "Tattica: Due gruppi tank ai due estremi, Stregoni su Vek'lor, Guerrieri su Vek'nilash. Dopo ogni teletrasporto riprenderli subito."
L["ZWILLINGE: Brüder auseinander halten! Nach Teleport Tanks sofort übernehmen!"] = "GEMELLI: Tenere separati i fratelli! Dopo il teletrasporto i tank li riprendono subito!"
L["Nahkampf nur Vek'nilash, Magie nur Vek'lor. Käfer töten."] = "Melee solo su Vek'nilash, magia solo su Vek'lor. Uccidere gli insetti."
L["Ouro + Skarabäen"] = "Ouro + scarabei"
L["- Fegen: Rückstoß und Betäubung im Umkreis -> Tanks rotieren."] = "- Spazzata: respinta e stun ad area -> ruotare i tank."
L["- Sandstoß: großer Frontalkegel -> nur Tanks vor Ouro."] = "- Esplosione di Sabbia: grande cono frontale -> solo i tank davanti a Ouro."
L["- Untertauchen: Erdhügel verfolgen Spieler, Skarabäen erscheinen -> weglaufen, Skarabäen töten."] = "- Immersione: cumuli di terra inseguono i giocatori, appaiono scarabei -> scappare, uccidere gli scarabei."
L["- Ist niemand in Nahkampfreichweite, wirft er Felsbrocken; ab 20 % Berserker -> Burn."] = "- Se nessuno è a portata melee lancia massi; dal 20 % berserk -> burn."
L["Taktik: Mehrere Tanks halten Ouro im Nahkampf, Raid seitlich. Beim Untertauchen verteilen und Skarabäen töten."] = "Tattica: Più tank tengono Ouro in melee, raid sui lati. Durante l'Immersione sparpagliarsi e uccidere gli scarabei."
L["OURO: Nicht vor den Boss! Untertauchen: verteilen, Skarabäen töten!"] = "OURO: Non davanti al boss! Immersione: sparpagliarsi, uccidere gli scarabei!"
L["Immer ein Tank im Nahkampf, sonst Felsbrocken."] = "Sempre un tank in melee, altrimenti massi."
L["C'Thun + Tentakel"] = "C'Thun + tentacoli"
L["- Augenstrahl: springt auf Spieler in der Nähe -> Raid im Kreis mit Abstand verteilen."] = "- Raggio Oculare: salta sui giocatori vicini -> raid disposto in cerchio con distanza."
L["- Dunkles Starren: rotierender Todesstrahl -> sofort zur Seite."] = "- Sguardo Oscuro: raggio mortale rotante -> spostarsi subito di lato."
L["- Tentakel: Augen- und Klauententakel erscheinen -> schnell töten."] = "- Tentacoli: appaiono tentacoli oculari e artigliati -> ucciderli in fretta."
L["- Phase 2: Spieler werden verschlungen; im Magen Fleischtentakel töten, um C'Thun zu schwächen -> nur in der Schwächephase Schaden."] = "- Fase 2: i giocatori vengono inghiottiti; nello stomaco uccidere i tentacoli di carne per indebolire C'Thun -> danno solo nella fase di debolezza."
L["Taktik: Feste Kreisaufstellung mit Abstand, Tentakel sofort weg. In Phase 2 Magen-Team tötet die Fleischtentakel, Raid zündet in der Schwächephase."] = "Tattica: Disposizione fissa in cerchio con distanza, tentacoli via subito. In fase 2 il team stomaco uccide i tentacoli di carne, il raid fa burst nella fase di debolezza."
L["C'THUN: Abstand halten! Dunkles Starren ausweichen, Tentakel sofort töten!"] = "C'THUN: Tenere la distanza! Schivare lo Sguardo Oscuro, uccidere subito i tentacoli!"
L["Phase 2: Magen-Team auf Fleischtentakel, Schaden in Schwäche."] = "Fase 2: team stomaco sui tentacoli di carne, danno durante la debolezza."
L["Pechschwingenhort"] = "Fauci dell'Ala Nera"
L["Razorgore der Ungezähmte + Adds der Schwarzen Drachenbrut"] = "Razorgore l'Indomito + add della Stirpe Nera"
L["- Phase 1: Ein Spieler kontrolliert Razorgore über die Kugel und zerstört mit ihm die Eier."] = "- Fase 1: un giocatore controlla Razorgore tramite il globo e con lui distrugge le uova."
L["- Adds: Drachenbrut, Drachkin und Magier strömen aus den Eingängen -> an den Eingängen tanken und töten."] = "- Add: draghetti, draconidi e maghi escono dagli ingressi -> tankarli e ucciderli agli ingressi."
L["- Kugel-Kontrolle: Kontrolleur nicht unterbrechen, Bedrohung für Phase 2 beachten."] = "- Controllo del globo: non interrompere il controllore, attenzione all'aggro per la fase 2."
L["- Phase 2: Razorgore wird frei, Feuerballsalve und Eroberung -> Tank bereit, Raid verteilt."] = "- Fase 2: Razorgore si libera, Raffica di Palle di Fuoco e Conquista -> tank pronto, raid sparso."
L["Taktik: Gruppen an den Eingängen halten die Adds, der Kontrolleur zerstört alle Eier. Phase 2: Tank übernimmt Razorgore sofort."] = "Tattica: Gruppi agli ingressi tengono gli add, il controllore distrugge tutte le uova. Fase 2: il tank prende subito Razorgore."
L["RAZORGORE: Eier zerstören, Adds an den Eingängen halten!"] = "RAZORGORE: Distruggere le uova, tenere gli add agli ingressi!"
L["Kugel-Kontrolleur nicht unterbrechen. Phase 2: Tank bereit."] = "Non interrompere il controllore del globo. Fase 2: tank pronto."
L["Vaelastrasz der Verdorbene"] = "Vaelastrasz il Corrotto"
L["- Essenz des Roten: alle Spieler haben unbegrenzt Mana/Wut/Energie -> durchgehend Vollgas."] = "- Essenza del Rosso: tutti i giocatori hanno mana/ira/energia illimitati -> a tutta birra senza sosta."
L["- Brennendes Adrenalin: Spieler explodiert nach kurzer Zeit und stirbt -> sofort aus dem Raid laufen; auf dem Tank -> Tankwechsel."] = "- Adrenalina Ardente: il giocatore esplode dopo poco e muore -> uscire subito dal raid; sul tank -> cambio tank."
L["- Flammenatem/Schwanzfeger: vorne und hinten gefährlich -> nur Tank vorne, Raid seitlich."] = "- Soffio di Fiamme/Colpo di Coda: pericolosi davanti e dietro -> solo il tank davanti, raid sui lati."
L["Taktik: Tank-Reihenfolge festlegen, Raid seitlich am Boss. Vael startet bei 30 % Leben: schnell töten, bevor zu viele Spieler sterben."] = "Tattica: Stabilire l'ordine dei tank, raid sui lati del boss. Vael parte al 30 % di vita: ucciderlo in fretta prima che muoiano troppi giocatori."
L["VAELASTRASZ: Brennendes Adrenalin -> sofort raus aus dem Raid!"] = "VAELASTRASZ: Adrenalina Ardente -> subito fuori dal raid!"
L["Nur seitlich stehen. Tank-Reihenfolge einhalten, Vollgas!"] = "Stare solo sui lati. Rispettare l'ordine dei tank, a tutta birra!"
L["Brutwächter Dreschbringer"] = "Signore della Covata Lashlayer"
L["- Tödlicher Stoß: senkt die Heilung auf dem Tank -> Heiler aufmerksam, Tank mit Abklingzeiten."] = "- Colpo Mortale: riduce le cure sul tank -> healer attenti, tank con i CD."
L["- Druckwelle: Feuerschaden im Umkreis -> Nahkampf heilen, Fernkampf auf Abstand."] = "- Onda d'Urto: danno da fuoco ad area -> curare i melee, ranged a distanza."
L["- Wegschlagen: senkt Bedrohung und wirft den Tank weg -> Tank mit dem Rücken zur Wand, Zweittank hoch in der Bedrohung."] = "- Colpo Spazzante: riduce l'aggro e scaraventa via il tank -> tank con la schiena al muro, secondo tank alto in aggro."
L["Taktik: Vorher den Unterdrückungsraum säubern. Boss mit dem Rücken des Tanks zur Wand tanken, Zweittank als Ersatz bereit."] = "Tattica: Prima pulire la sala della soppressione. Tankare il boss con la schiena del tank al muro, secondo tank pronto come riserva."
L["BRUTWÄCHTER: Tank an die Wand! Zweittank Bedrohung hoch halten!"] = "LASHLAYER: Tank al muro! Secondo tank tiene alta l'aggro!"
L["Tödlicher Stoß: Tank stark heilen. Fernkampf auf Abstand."] = "Colpo Mortale: curare forte il tank. Ranged a distanza."
L["Feuerschwinge"] = "Firemaw"
L["- Flammenpuffer: stapelnder Feuer-Debuff auf allen in Sichtlinie -> hinter Säulen Stapel abbauen."] = "- Respingente di Fiamme: debuff di fuoco a stack su tutti in linea di vista -> smaltire gli stack dietro le colonne."
L["- Flügelstoß: senkt Bedrohung, wirft zurück -> Tankwechsel einplanen."] = "- Battito d'Ali: riduce l'aggro, respinge -> prevedere il cambio tank."
L["- Schattenflamme: Frontalkegel -> Onyxiaschuppenumhang tragen, nur Tank vorne."] = "- Fiamma d'Ombra: cono frontale -> indossare il Mantello di Scaglie di Onyxia, solo il tank davanti."
L["Taktik: Zwei Tanks wechseln bei Flügelstoß, Fernkampf und Heiler pendeln zwischen Sichtlinie und Säule, um Stapel abzubauen."] = "Tattica: Due tank si alternano a ogni Battito d'Ali, ranged e healer fanno avanti e indietro tra linea di vista e colonna per smaltire gli stack."
L["FEUERSCHWINGE: Stapel hinter der Säule abbauen! Umhang an!"] = "FIREMAW: Smaltire gli stack dietro la colonna! Mantello addosso!"
L["Tankwechsel bei Flügelstoß. Nur Tank vorne."] = "Cambio tank su Battito d'Ali. Solo il tank davanti."
L["Schattenschwinge"] = "Ebonroc"
L["- Schatten von Schattenschwinge: Debuff auf dem Tank, jeder Treffer heilt den Boss -> sofort Tankwechsel."] = "- Ombra di Ebonroc: debuff sul tank, ogni colpo cura il boss -> cambio tank immediato."
L["- Flügelstoß: senkt Bedrohung -> Zweittank bereit."] = "- Battito d'Ali: riduce l'aggro -> secondo tank pronto."
L["Taktik: Zwei Tanks wechseln bei jedem Schatten-Debuff, Raid seitlich. Mit Umhängen ist der Kampf ruhig."] = "Tattica: Due tank si alternano a ogni debuff d'ombra, raid sui lati. Con i mantelli lo scontro è tranquillo."
L["SCHATTENSCHWINGE: Tankwechsel bei Schatten-Debuff! Umhang an!"] = "EBONROC: Cambio tank sul debuff d'ombra! Mantello addosso!"
L["Nur Tank vorne, Raid seitlich am Boss."] = "Solo il tank davanti, raid sui lati del boss."
L["Flammenmaul"] = "Flamegor"
L["- Raserei: mehr Schaden auf den Tank -> Jäger mit Einlullender Schuss sofort entfernen."] = "- Frenesia: più danno sul tank -> Cacciatori la rimuovono subito con Tiro Tranquillizzante."
L["- Feuernova: Feuerschaden auf den ganzen Raid -> Heiler aufmerksam, Feuerwiderstand hilft."] = "- Nova di Fuoco: danno da fuoco su tutto il raid -> healer attenti, la resistenza al fuoco aiuta."
L["- Flügelstoß und Schattenflamme: Bedrohungsverlust und Frontalkegel -> Tankwechsel, Umhang, nur Tank vorne."] = "- Battito d'Ali e Fiamma d'Ombra: perdita di aggro e cono frontale -> cambio tank, mantello, solo il tank davanti."
L["Taktik: Zwei Tanks, Jäger-Rotation für Einlullender Schuss, Raid seitlich und verteilt."] = "Tattica: Due tank, rotazione dei Cacciatori per Tiro Tranquillizzante, raid sui lati e sparso."
L["FLAMMENMAUL: Raserei sofort einlullen! Umhang an!"] = "FLAMEGOR: Frenesia subito tranquillizzata! Mantello addosso!"
L["Tankwechsel bei Flügelstoß, Feuernova gegenheilen."] = "Cambio tank su Battito d'Ali, curare la Nova di Fuoco."
L["Schattenschwinge und Flammenmaul (gemeinsame Begegnung)"] = "Ebonroc e Flamegor (scontro combinato)"
L["- Gemeinsamer Kampf: beide Drachen gleichzeitig -> getrennt tanken, Fernkampf zwischen beiden aufteilen."] = "- Scontro combinato: entrambi i draghi insieme -> tankare separati, dividere i ranged tra i due."
L["- Schatten von Schattenschwinge: Treffer auf dem betroffenen Tank heilen den Drachen -> sofort Tankwechsel."] = "- Ombra di Ebonroc: i colpi sul tank colpito curano il drago -> cambio tank immediato."
L["- Raserei (Flammenmaul): sofort mit Einlullender Schuss entfernen."] = "- Frenesia (Flamegor): rimuoverla subito con Tiro Tranquillizzante."
L["- Schattenflamme und Flügelstoß: Frontalkegel und Bedrohungsverlust -> Umhang, nur Tanks vorne."] = "- Fiamma d'Ombra e Battito d'Ali: cono frontale e perdita di aggro -> mantello, solo i tank davanti."
L["Taktik: Je zwei Tanks pro Drache, Drachen voneinander weg und seitlich zum Raid ausrichten. Ein Drache nach dem anderen fokussieren."] = "Tattica: Due tank per drago, draghi lontani tra loro e girati di lato rispetto al raid. Focus su un drago alla volta."
L["Nur in Classic-Versionen, in denen beide Drachen gemeinsam bekämpft werden."] = "Solo nelle versioni Classic in cui i due draghi si affrontano insieme."
L["DRACHEN: Getrennt tanken! Tankwechsel bei Schatten, Raserei einlullen!"] = "DRAGHI: Tankare separati! Cambio tank sull'Ombra, Frenesia tranquillizzata!"
L["Umhang an, nur Tanks vorne. Fokus laut Symbol."] = "Mantello addosso, solo i tank davanti. Focus secondo il simbolo."
L["Schattenschwinge/Flammenmaul"] = "Ebonroc/Flamegor"
L["Totenkopf auf den Drachen, der zuerst stirbt, Kreuz auf den zweiten."] = "Teschio sul drago che muore per primo, croce sul secondo."
L["Chromaggus"] = "Chromaggus"
L["- Atem: zwei von fünf Atemarten pro ID (z. B. Verbrennen, Ätzende Säure, Frostbrand, Zeitraffer, Fleisch entzünden) -> hinter die Wand in Deckung gehen."] = "- Soffio: due dei cinque tipi di soffio per ID (es. Incenerimento, Acido Corrosivo, Morso del Gelo, Lasso Temporale, Accendi Carne) -> ripararsi dietro il muro."
L["- Brutgebrechen: fünf farbige Debuffs; Bronze nur mit Sand des Stundenglases entfernbar -> bannen, entfluchen, Gift/Krankheit heilen."] = "- Afflizione della Stirpe: cinque debuff colorati; il bronzo si rimuove solo con la Sabbia della Clessidra -> dispel, decurse, curare veleno/malattia."
L["- Raserei: Jäger mit Einlullender Schuss; ab 20 % Wutanfall -> Burn."] = "- Frenesia: Cacciatori con Tiro Tranquillizzante; dal 20 % Ira -> burn."
L["- Wechselnde Verwundbarkeit: Chromaggus wird gegen eine Schule anfällig -> passende Zauber nutzen."] = "- Vulnerabilità variabile: Chromaggus diventa vulnerabile a una scuola -> usare gli incantesimi adatti."
L["Taktik: Tank zieht Chromaggus an den Eingang, Raid steht für die Atemangriffe hinter der Mauer in Deckung. Debuffs sofort entfernen."] = "Tattica: Il tank porta Chromaggus all'ingresso, il raid si ripara dietro il muro per i soffi. Rimuovere subito i debuff."
L["CHROMAGGUS: Bei Atem hinter die Wand! Brutgebrechen sofort entfernen!"] = "CHROMAGGUS: Al soffio dietro il muro! Rimuovere subito le afflizioni!"
L["Raserei einlullen, Sand für Bronze bereithalten. Ab 20 % Burn."] = "Frenesia tranquillizzata, Sabbia pronta per il bronzo. Dal 20 % burn."
L["Nefarian + Drakoniden"] = "Nefarian + draconidi"
L["- Phase 1: Drakoniden zweier Farben aus beiden Seiten -> an beiden Seiten tanken und töten, bis Nefarian landet."] = "- Fase 1: draconidi di due colori da entrambi i lati -> tankarli e ucciderli su entrambi i lati finché Nefarian atterra."
L["- Dröhnendes Gebrüll: Furcht auf alle -> Furchtschutz, Tremorstotem, Tanks mit Berserkerwut."] = "- Ruggito Rimbombante: paura su tutti -> Protezione dalla Paura, Totem del Tremore, tank con Furia del Berserker."
L["- Klassenrufe: Klassen erhalten negative Effekte -> je nach Ruf reagieren (z. B. Krieger Haltung, Priester nicht heilen)."] = "- Chiamate di classe: le classi ricevono effetti negativi -> reagire secondo la chiamata (es. Guerrieri postura, Sacerdoti non curare)."
L["- Schleier der Schatten/Schattenflamme: Heilungsreduktion und Frontalkegel -> entfluchen, Umhang, nur Tank vorne."] = "- Velo d'Ombra/Fiamma d'Ombra: riduzione cure e cono frontale -> decurse, mantello, solo il tank davanti."
L["- Phase 3 bei 20 %: tote Drakoniden erstehen als Skelette -> Offtanks sammeln, Fokus Nefarian."] = "- Fase 3 al 20 %: i draconidi morti risorgono come scheletri -> gli offtank li raccolgono, focus su Nefarian."
L["Taktik: Zwei Gruppen halten in Phase 1 die Drakoniden. Phase 2 Nefarian mit Rücken zur Wand tanken, Raid seitlich, auf Klassenrufe achten."] = "Tattica: In fase 1 due gruppi tengono i draconidi. Fase 2 tankare Nefarian con la schiena al muro, raid sui lati, attenzione alle chiamate di classe."
L["NEFARIAN: Furchtschutz bereit! Auf Klassenrufe reagieren!"] = "NEFARIAN: Protezione dalla Paura pronta! Reagire alle chiamate di classe!"
L["Nur Tank vorne, Umhang an. Phase 3: Skelette sammeln, Fokus Nef."] = "Solo il tank davanti, mantello addosso. Fase 3: raccogliere gli scheletri, focus su Nef."
L["Naxxramas"] = "Naxxramas"
L["Anub'Rekhan + Gruftwächter"] = "Anub'Rekhan + Guardie della Cripta"
L["- Heuschreckenschwarm: Anub'Rekhan wird schneller und verursacht viel Schaden -> Tank kitet ihn durch den Raum."] = "- Sciame di Locuste: Anub'Rekhan diventa più veloce e fa molto danno -> il tank lo kita per la stanza."
L["- Aufspießen: Linie mit Hochschleudern -> nicht in einer Linie mit dem Boss stehen."] = "- Impalamento: linea con lancio in aria -> non stare in linea con il boss."
L["- Gruftwächter: kommen zu Beginn und während des Kampfes -> Offtank übernimmt, zuerst töten."] = "- Guardie della Cripta: arrivano all'inizio e durante lo scontro -> le prende l'offtank, uccidere per prime."
L["- Leichenskarabäen: aus getöteten Spielern/Adds -> mit Flächenschaden töten."] = "- Scarabei Cadaverici: escono da giocatori/add morti -> ucciderli ad AoE."
L["Taktik: Wächter zuerst töten, Raid verteilt seitlich. Beim Heuschreckenschwarm kitet der Tank Anub'Rekhan im großen Kreis durch den Raum."] = "Tattica: Uccidere prima le guardie, raid sparso sui lati. Durante lo Sciame di Locuste il tank kita Anub'Rekhan in un grande cerchio per la stanza."
L["ANUB'REKHAN: Heuschreckenschwarm -> Tank kitet, Raid ausweichen!"] = "ANUB'REKHAN: Sciame di Locuste -> il tank kita, raid schiva!"
L["Gruftwächter zuerst. Nicht in Linie für Aufspießen."] = "Prima le Guardie della Cripta. Non in linea per l'Impalamento."
L["Großwitwe Faerlina + Anhänger und Verehrer"] = "Gran Vedova Faerlina + seguaci e adoratori"
L["- Raserei: hoher Tankschaden -> Verehrer in ihrer Nähe sterben lassen (Umarmung der Witwe), Raserei endet."] = "- Frenesia: alto danno sul tank -> far morire un adoratore vicino a lei (Abbraccio della Vedova), la frenesia finisce."
L["- Feuerregen: Feuerzone -> sofort verlassen."] = "- Pioggia di Fuoco: zona di fuoco -> uscirne subito."
L["- Giftblitzsalve: Naturschaden auf Gruppen -> Gift entfernen, Naturwiderstand hilft."] = "- Raffica di Dardi Velenosi: danno da natura sui gruppi -> rimuovere il veleno, la resistenza alla natura aiuta."
L["- Anhänger: Ansturm und Stille -> zuerst töten."] = "- Seguaci: carica e silenzio -> uccidere per primi."
L["Taktik: Anhänger zuerst töten, Verehrer per Gedankenkontrolle der Priester aufsparen und bei Raserei neben Faerlina opfern."] = "Tattica: Uccidere prima i seguaci, tenere da parte gli adoratori col controllo mentale dei Sacerdoti e sacrificarli accanto a Faerlina durante la frenesia."
L["FAERLINA: Anhänger zuerst! Verehrer für Raserei aufheben!"] = "FAERLINA: Prima i seguaci! Tenere gli adoratori per la frenesia!"
L["Raus aus dem Feuerregen, Gift entfernen."] = "Fuori dalla Pioggia di Fuoco, rimuovere il veleno."
L["Faerlina"] = "Faerlina"
L["Totenkopf/Kreuz auf die Anhänger (zuerst töten), Stern bis Dreieck auf die Verehrer für die Priester."] = "Teschio/croce sui seguaci (uccidere per primi), da stella a triangolo sugli adoratori per i Sacerdoti."
L["Maexxna + Spinnenjunge"] = "Maexxna + piccoli di ragno"
L["- Netzspray: betäubt den ganzen Raid ca. 8 Sek. -> vorher Tank voll heilen, HoTs drauf."] = "- Spruzzo di Ragnatela: stunna tutto il raid per circa 8 sec. -> prima curare full il tank, HoT addosso."
L["- Netzwirbel: Spieler werden an die Wand gesponnen -> Fernkampf befreit sie sofort."] = "- Avvolgimento: i giocatori vengono avvolti al muro -> i ranged li liberano subito."
L["- Nekrotisches Gift: senkt Heilung auf dem Tank -> Gift sofort entfernen."] = "- Veleno Necrotico: riduce le cure sul tank -> rimuovere subito il veleno."
L["- Spinnenjunge: werden regelmäßig ausgespuckt -> Flächenschaden; ab 30 % Raserei -> Burn."] = "- Piccoli di ragno: vengono sputati regolarmente -> AoE; dal 30 % frenesia -> burn."
L["Taktik: Tank in der Mitte, Fernkampf befreit Eingesponnene, Heiler bereiten jedes Netzspray mit Vorheilung vor."] = "Tattica: Tank al centro, i ranged liberano gli avvolti, gli healer preparano ogni Spruzzo di Ragnatela con pre-cure."
L["MAEXXNA: Vor Netzspray Tank voll heilen! Eingesponnene sofort befreien!"] = "MAEXXNA: Prima dello Spruzzo di Ragnatela tank full! Liberare subito gli avvolti!"
L["Nekrotisches Gift entfernen, Spinnenjunge per Flächenschaden."] = "Rimuovere il Veleno Necrotico, piccoli di ragno ad AoE."
L["Noth der Seuchenfürst + Seuchenkrieger"] = "Noth il Portapiaghe + guerrieri della piaga"
L["- Fluch des Seuchenfürsten: bei Ablauf Schaden auf Spieler und Umgebung -> sofort entfluchen."] = "- Maledizione del Portapiaghe: allo scadere danno sul giocatore e intorno -> decurse immediato."
L["- Blinzeln: Noth teleportiert und setzt Bedrohung zurück -> Tanks schnell übernehmen."] = "- Traslazione: Noth si teletrasporta e azzera l'aggro -> i tank lo riprendono in fretta."
L["- Balkon-Phase: Noth teleportiert sich weg, Wellen von Skeletten -> Offtanks sammeln, Flächenschaden."] = "- Fase balcone: Noth si teletrasporta via, ondate di scheletri -> gli offtank li raccolgono, AoE."
L["Taktik: Entfluchen fest einteilen, Tanks in den Ecken bereit. Adds in den Balkon-Phasen sammeln und schnell töten."] = "Tattica: Decurse assegnati fissi, tank pronti negli angoli. Nelle fasi balcone raccogliere gli add e ucciderli in fretta."
L["NOTH: Flüche sofort entfernen! Nach Blinzeln Tank übernehmen!"] = "NOTH: Rimuovere subito le maledizioni! Dopo la Traslazione il tank lo riprende!"
L["Balkon-Phase: Adds sammeln und mit Flächenschaden töten."] = "Fase balcone: raccogliere gli add e ucciderli ad AoE."
L["Heigan der Unreine"] = "Heigan l'Impuro"
L["- Ausbruch: der Boden bricht in Zonen nacheinander aus -> im Takt die Zonen wechseln (Tanzen)."] = "- Eruzione: il pavimento erutta a zone una dopo l'altra -> cambiare zona a tempo (la danza)."
L["- Zauberunterbrechung/Manabrand: in der Nähe Zauberverlangsamung -> Fernkampf auf der Plattform weg."] = "- Interruzione/Bruciatura di mana: rallentamento dei lanci nelle vicinanze -> ranged lontani sulla piattaforma."
L["- Fieberhafte Krankheit: Krankheits-Debuff, senkt Leben -> Krankheit heilen."] = "- Malattia Febbrile: debuff di malattia, riduce la vita -> curare la malattia."
L["- Tanz-Phase: Heigan teleportiert auf die Plattform, schnellere Ausbrüche -> alle tanzen mit."] = "- Fase danza: Heigan si teletrasporta sulla piattaforma, eruzioni più rapide -> tutti ballano."
L["Taktik: Tank führt Heigan im Takt durch die Zonen, Fernkampf auf der Plattform. In der Tanz-Phase alle zusammen der Zonenreihenfolge folgen."] = "Tattica: Il tank porta Heigan a tempo attraverso le zone, ranged sulla piattaforma. Nella fase danza tutti insieme seguono l'ordine delle zone."
L["HEIGAN: Im Takt die Zonen wechseln! Nicht im Ausbruch stehen!"] = "HEIGAN: Cambiare zona a tempo! Non stare nell'Eruzione!"
L["Krankheit heilen. Tanz-Phase: alle zusammen dem Tank folgen."] = "Curare la malattia. Fase danza: tutti insieme seguono il tank."
L["Loatheb + Sporen"] = "Loatheb + spore"
L["- Verderbter Geist: Heiler können nur ca. einmal pro Minute heilen -> feste Heilrotation."] = "- Mente Corrotta: gli healer possono curare solo circa una volta al minuto -> rotazione di cure fissa."
L["- Unausweichliches Schicksal: hoher Schattenschaden nach kurzer Zeit -> Schattenschutz-Tränke, rechtzeitig heilen."] = "- Fato Inevitabile: alto danno d'ombra dopo poco -> pozioni di protezione dall'ombra, curare in tempo."
L["- Sporen: getötete Spore gibt nahen Spielern kritische Treffer -> Gruppen nacheinander in die Spore."] = "- Spore: una spora uccisa dà critici ai giocatori vicini -> i gruppi entrano nella spora uno alla volta."
L["Taktik: Strikte Heilrotation, Schattenschutz-Tränke vorher. Sporen gruppenweise für Kritbonus nutzen und Schaden maximieren."] = "Tattica: Rotazione di cure rigida, pozioni di protezione dall'ombra prima. Usare le spore a gruppi per il bonus critico e massimizzare il danno."
L["LOATHEB: Heilrotation einhalten! Schattenschutz-Trank nutzen!"] = "LOATHEB: Rispettare la rotazione di cure! Usare la pozione di protezione dall'ombra!"
L["Sporen gruppenweise nutzen für kritische Treffer."] = "Usare le spore a gruppi per i colpi critici."
L["Instrukteur Razuvious + 4 Todesritter-Reservisten"] = "Istruttore Razuvious + 4 Riservisti Cavalieri della Morte"
L["- Schwere Nahkampfschläge: töten normale Tanks fast sofort -> nur gedankenkontrollierte Reservisten tanken ihn."] = "- Colpi melee pesanti: uccidono quasi subito i tank normali -> lo tankano solo i riservisti sotto controllo mentale."
L["- Störender Schrei: Manabrand und Schaden im Umkreis -> Abstand halten."] = "- Urlo Destabilizzante: bruciatura di mana e danno ad area -> tenere la distanza."
L["- Gedankenkontrolle: Priester steuern die Reservisten (Schildwall, Spott) -> Kontrolle rechtzeitig wechseln."] = "- Controllo mentale: i Sacerdoti guidano i riservisti (Muro di Scudi, Provocazione) -> cambiare il controllo in tempo."
L["Taktik: Priester übernehmen je einen Reservisten und wechseln die Rolle als Tank, Fernkampf auf Distanz, Nahkampf am Boss."] = "Tattica: Ogni Sacerdote prende un riservista e si alternano come tank, ranged a distanza, melee sul boss."
L["RAZUVIOUS: Nur Reservisten tanken! Priester Kontrolle rechtzeitig wechseln!"] = "RAZUVIOUS: Tankano solo i riservisti! Sacerdoti cambiano il controllo in tempo!"
L["Abstand wegen Störender Schrei."] = "Distanza per l'Urlo Destabilizzante."
L["Razuvious (Reservisten)"] = "Razuvious (riservisti)"
L["Jeder Reservist ein Symbol, jeder Priester übernimmt sein zugewiesenes Symbol."] = "Ogni riservista un simbolo, ogni Sacerdote prende il simbolo assegnato."
L["Gothik der Seelenjäger + Lebende und Untote"] = "Gothik il Mietitore + vivi e non morti"
L["- Zwei Seiten: Raid aufgeteilt in lebende und tote Seite -> beide Seiten gleich stark besetzen."] = "- Due lati: raid diviso in lato dei vivi e lato dei morti -> stessa forza su entrambi i lati."
L["- Lebende Adds: sterben sie, erscheinen sie als Geister auf der toten Seite -> tote Seite muss mithalten."] = "- Add vivi: quando muoiono appaiono come spiriti sul lato dei morti -> il lato dei morti deve tenere il passo."
L["- Tor: öffnet nach einiger Zeit, dann kommt Gothik herunter -> Adds vorher unter Kontrolle haben."] = "- Cancello: si apre dopo un po', poi scende Gothik -> avere prima gli add sotto controllo."
L["- Seele ernten: stapelnder Debuff -> zügig töten."] = "- Mietitura dell'Anima: debuff a stack -> ucciderlo in fretta."
L["Taktik: Raid in zwei Hälften, jede Seite tötet ihre Wellen. Nach Öffnen des Tores Gothik tanken und schnell töten."] = "Tattica: Raid in due metà, ogni lato uccide le sue ondate. All'apertura del cancello tankare Gothik e ucciderlo in fretta."
L["GOTHIK: Beide Seiten halten! Tote Seite auf Geister vorbereiten!"] = "GOTHIK: Tenere entrambi i lati! Lato dei morti pronto per gli spiriti!"
L["Nach dem Tor: Gothik schnell töten."] = "Dopo il cancello: uccidere Gothik in fretta."
L["Die Vier Reiter: Thane Korth'azz, Lady Blaumeux, Hochlord Mograine, Sir Zeliek"] = "I Quattro Cavalieri: Thane Korth'azz, Lady Blaumeux, Gran Lord Mograine, Sir Zeliek"
L["- Male: jeder Reiter stapelt sein Mal, hohe Stapel töten -> Tanks rotieren zwischen den Reitern."] = "- Marchi: ogni cavaliere accumula il suo marchio, stack alti uccidono -> i tank ruotano tra i cavalieri."
L["- Meteor (Korth'azz): Schaden geteilt auf getroffene Spieler -> bei ihm zusammenstehen."] = "- Meteora (Korth'azz): danno diviso tra i giocatori colpiti -> stare vicini a lui."
L["- Leerezone (Blaumeux): Schattenfläche -> herauslaufen."] = "- Zona del Vuoto (Blaumeux): area d'ombra -> uscirne."
L["- Heiliger Zorn (Zeliek): springt zwischen Spielern -> verteilt stehen."] = "- Ira Sacra (Zeliek): rimbalza tra i giocatori -> stare sparsi."
L["Taktik: Reiter in die vier Ecken ziehen, Tanks und Heiler rotieren nach festem Plan, um Mal-Stapel abzubauen. Zwei Reiter nacheinander fokussieren."] = "Tattica: Portare i cavalieri nei quattro angoli, tank e healer ruotano secondo un piano fisso per smaltire gli stack dei marchi. Focus su due cavalieri uno dopo l'altro."
L["VIER REITER: Rotation einhalten! Male nicht zu hoch stapeln!"] = "QUATTRO CAVALIERI: Rispettare la rotazione! Non accumulare troppi marchi!"
L["Meteor: zusammen. Zeliek: verteilt. Leerezone verlassen."] = "Meteora: insieme. Zeliek: sparsi. Uscire dalla Zona del Vuoto."
L["Flickwerk"] = "Patchwerk"
L["- Hasserfüllter Schlag: trifft den Nahkampf-Spieler mit dem meisten Leben (nicht den Haupttank) -> drei Offtanks mit voller Gesundheit soaken."] = "- Colpo d'Odio: colpisce il melee con più vita (non il main tank) -> tre offtank a vita piena assorbono."
L["- Berserker nach ca. 7 Minuten: Raid stirbt -> Schaden maximieren."] = "- Berserk dopo circa 7 minuti: il raid muore -> massimizzare il danno."
L["- Raserei ab 5 %: mehr Schaden -> Heiler voll auf die Tanks."] = "- Frenesia dal 5 %: più danno -> healer tutti sui tank."
L["Taktik: Haupttank plus drei Offtanks mit hohem Leben im Nahkampf, Heiler fest auf die Tanks eingeteilt, alle anderen maximaler Schaden."] = "Tattica: Main tank più tre offtank con molta vita in melee, healer assegnati fissi sui tank, tutti gli altri DPS massimo."
L["FLICKWERK: Offtanks mit vollem Leben im Nahkampf! Volles DPS!"] = "PATCHWERK: Offtank a vita piena in melee! DPS al massimo!"
L["Heiler nur auf die Tanks. Berserker-Timer beachten."] = "Healer solo sui tank. Attenzione al timer del berserk."
L["Grobbulus + Brühschleime"] = "Grobbulus + melme fetide"
L["- Mutierende Injektion: Spieler explodiert nach Ablauf mit Giftwolke -> an den Rand laufen, erst dort bannen/ablaufen lassen."] = "- Iniezione Mutante: allo scadere il giocatore esplode con una nube tossica -> correre al bordo, solo lì dispellare/lasciar scadere."
L["- Schleimspray: Kegel vor dem Boss, ruft Brühschleime -> Raid nicht vorne, Schleime töten."] = "- Spruzzo di Melma: cono davanti al boss, evoca melme -> raid non davanti, uccidere le melme."
L["- Giftwolken: bleiben liegen -> Tank zieht Grobbulus langsam am Rand entlang."] = "- Nubi tossiche: restano a terra -> il tank porta Grobbulus lentamente lungo il bordo."
L["Taktik: Tank kitet Grobbulus langsam um den Raum, Raid hinten/seitlich, betroffene Spieler laufen mit Injektion an die Seite."] = "Tattica: Il tank kita Grobbulus lentamente intorno alla stanza, raid dietro/sui lati, chi ha l'iniezione corre di lato."
L["GROBBULUS: Injektion -> an den Rand laufen! Nicht vor den Boss!"] = "GROBBULUS: Iniezione -> correre al bordo! Non davanti al boss!"
L["Schleime töten, Giftwolken meiden, Tank kitet am Rand."] = "Uccidere le melme, evitare le nubi tossiche, il tank kita lungo il bordo."
L["Gluth + Zombies"] = "Gluth + zombi"
L["- Tödliche Wunde: Heilungsreduktions-Stapel -> Tankwechsel."] = "- Ferita Mortale: stack di riduzione cure -> cambio tank."
L["- Dezimieren: bringt alle auf ca. 5 % Leben, Zombies laufen zu Gluth und heilen ihn -> Zombies kiten und mit Flächenschaden töten."] = "- Decimazione: porta tutti a circa 5 % di vita, gli zombi corrono da Gluth e lo curano -> kitare gli zombi e ucciderli ad AoE."
L["- Raserei: Jäger mit Einlullender Schuss."] = "- Frenesia: Cacciatori con Tiro Tranquillizzante."
L["- Schreckliches Gebrüll: Furcht -> Furchtschutz für Tanks."] = "- Ruggito Terrificante: paura -> Protezione dalla Paura sui tank."
L["Taktik: Zwei Tanks wechseln, ein Kiter mit Fallen hält die Zombies vom Boss weg. Nach Dezimieren Zombies sofort mit Flächenschaden töten."] = "Tattica: Due tank si alternano, un kiter con trappole tiene gli zombi lontani dal boss. Dopo la Decimazione uccidere subito gli zombi ad AoE."
L["GLUTH: Zombies kiten und töten! Raserei einlullen!"] = "GLUTH: Kitare e uccidere gli zombi! Frenesia tranquillizzata!"
L["Tankwechsel bei Tödlicher Wunde. Nach Dezimieren hochheilen."] = "Cambio tank su Ferita Mortale. Dopo la Decimazione cure di massa."
L["Thaddius + Stalagg und Feugen"] = "Thaddius + Stalagg e Feugen"
L["- Phase 1: Stalagg und Feugen auf zwei Plattformen -> beide gleichzeitig töten (kurzes Zeitfenster), sonst erwacht der andere wieder."] = "- Fase 1: Stalagg e Feugen su due piattaforme -> ucciderli entrambi insieme (finestra breve), altrimenti l'altro si rialza."
L["- Magnetzug: tauscht die Tanks zwischen den Plattformen -> Tanks bereit halten."] = "- Attrazione Magnetica: scambia i tank tra le piattaforme -> tank pronti."
L["- Polaritätsverschiebung: Plus- oder Minus-Ladung -> zur Gruppe mit gleicher Ladung laufen."] = "- Cambio di Polarità: carica positiva o negativa -> correre dal gruppo con la stessa carica."
L["- Kettenblitz und Berserker nach ca. 5 Minuten -> verteilt und schnell."] = "- Catena di Fulmini e berserk dopo circa 5 minuti -> sparsi e veloci."
L["Taktik: Phase 1 beide Adds gleichzeitig herunterbringen. Phase 2 feste Plus- und Minus-Seite, bei Polaritätswechsel sofort Seite wechseln."] = "Tattica: In fase 1 abbattere entrambi gli add insieme. In fase 2 lato più e lato meno fissi, al cambio di polarità cambiare subito lato."
L["THADDIUS: Plus links, Minus rechts! Bei Polaritätswechsel Seite wechseln!"] = "THADDIUS: Più a sinistra, meno a destra! Al cambio di polarità cambiare lato!"
L["Phase 1: Stalagg und Feugen gleichzeitig töten."] = "Fase 1: uccidere Stalagg e Feugen insieme."
L["Saphiron"] = "Sapphiron"
L["- Frostaura: dauerhafter Frostschaden -> Frostwiderstand für alle."] = "- Aura del Gelo: danno da gelo continuo -> resistenza al gelo per tutti."
L["- Lebensentzug: Fluch auf Spielern -> sofort entfluchen."] = "- Risucchio Vitale: maledizione sui giocatori -> decurse immediato."
L["- Flugphase: Eisblitz friert Spieler zu Eisblöcken -> danach hinter einem Eisblock vor Frostatem verstecken."] = "- Fase in volo: Dardo di Ghiaccio congela i giocatori in blocchi di ghiaccio -> poi nascondersi dietro un blocco dal Soffio di Gelo."
L["- Blizzard: wandernde Frostzonen -> ausweichen."] = "- Blizzard: zone di gelo che si muovono -> schivarle."
L["Taktik: Frostwiderstand-Ausrüstung pflicht. Tank hält Saphiron mit Kopf weg vom Raid, in der Flugphase alle verteilt und dann hinter Eisblock."] = "Tattica: Equip con resistenza al gelo obbligatorio. Il tank tiene la testa di Sapphiron lontana dal raid, nella fase in volo tutti sparsi e poi dietro un blocco di ghiaccio."
L["SAPHIRON: Hinter Eisblock bei Frostatem! Flüche sofort entfernen!"] = "SAPPHIRON: Dietro il blocco di ghiaccio al Soffio di Gelo! Rimuovere subito le maledizioni!"
L["Frostwiderstand an. Blizzard ausweichen."] = "Resistenza al gelo addosso. Schivare il Blizzard."
L["Kel'Thuzad + Adds"] = "Kel'Thuzad + add"
L["- Phase 1: Skelette, Abscheulichkeiten und Seelenweber -> am Rand der Nischen töten."] = "- Fase 1: scheletri, abomini e tessitori d'anime -> ucciderli al bordo delle nicchie."
L["- Frostblitz: sehr hoher Schaden -> unterbrechen."] = "- Dardo di Gelo: danno altissimo -> kickare."
L["- Frostschlag/Detonieren von Mana/Schattenspalt: Frost-Wurzeln, Manaexplosion und Bodenflächen -> heilen, Manaspieler raus, Spalt verlassen."] = "- Colpo di Gelo/Detonazione di Mana/Fenditura d'Ombra: radici di gelo, esplosione di mana e zone a terra -> curare, chi usa mana fuori, uscire dalla fenditura."
L["- Ketten von Kel'Thuzad: Gedankenkontrolle -> Spieler kontrollieren."] = "- Catene di Kel'Thuzad: controllo mentale -> controllare i giocatori."
L["- Phase 3 (45 %): Wächter von Eiskrone -> Priester fesseln die Untoten."] = "- Fase 3 (45 %): Guardiani di Corona di Ghiaccio -> i Sacerdoti incatenano i non morti."
L["Taktik: Raid verteilt in den Nischen, Unterbrecher-Rotation auf Frostblitz. Phase 3: Wächter per Untote fesseln binden."] = "Tattica: Raid sparso nelle nicchie, rotazione di kick sul Dardo di Gelo. Fase 3: bloccare i guardiani con Incatenare Non Morti."
L["KEL'THUZAD: Frostblitz unterbrechen! Schattenspalt sofort verlassen!"] = "KEL'THUZAD: Kickare il Dardo di Gelo! Uscire subito dalla Fenditura d'Ombra!"
L["Gedankenkontrollierte kontrollieren. Phase 3: Wächter fesseln."] = "Controllare chi è sotto mind control. Fase 3: incatenare i guardiani."
L["Kel'Thuzad (Wächter)"] = "Kel'Thuzad (guardiani)"
L["Jeder Wächter von Eiskrone ein Symbol, Priester fesseln ihr zugewiesenes Symbol (Stern zuerst)."] = "Ogni Guardiano di Corona di Ghiaccio un simbolo, i Sacerdoti incatenano il simbolo assegnato (prima la stella)."
L["Onyxias Hort"] = "Antro di Onyxia"
L["Onyxia + Welpen und Wachen"] = "Onyxia + cuccioli e guardie"
L["- Phase 2 (65 %): fliegt, Feuerbälle und Tiefer Atem -> aus der Atemlinie laufen, Welpen aus den Höhlen töten."] = "- Fase 2 (65 %): vola, palle di fuoco e Soffio Profondo -> uscire dalla linea del soffio, uccidere i cuccioli dalle grotte."
L["- Phase 3 (40 %): landet, Furcht (Gebrüll) und Bodenausbrüche -> Furchtschutz, Tremorstotem."] = "- Fase 3 (40 %): atterra, paura (ruggito) ed eruzioni dal suolo -> Protezione dalla Paura, Totem del Tremore."
L["- Flügelstoß: senkt Bedrohung -> Tank behält vorsichtig Aggro."] = "- Battito d'Ali: riduce l'aggro -> il tank tiene l'aggro con cautela."
L["Taktik: Phase 1 Onyxia mit Kopf zur Wand, Raid seitlich. Phase 2 verteilt, Welpen mit Flächenschaden. Phase 3 Tank übernimmt, Furcht beachten."] = "Tattica: Fase 1 Onyxia con la testa al muro, raid sui lati. Fase 2 sparsi, cuccioli ad AoE. Fase 3 il tank la riprende, attenzione alla paura."
L["ONYXIA: Nicht vor oder hinter den Drachen! Tiefer Atem: aus der Linie!"] = "ONYXIA: Non davanti o dietro al drago! Soffio Profondo: fuori dalla linea!"
L["Welpen sofort töten. Phase 3: Furchtschutz bereit."] = "Uccidere subito i cuccioli. Fase 3: Protezione dalla Paura pronta."
L["Zul'Gurub"] = "Zul'Gurub"
L["Hohepriesterin Jeklik + Fledermäuse"] = "Somma Sacerdotessa Jeklik + pipistrelli"
L["- Phase 1 (Fledermausform): Ansturm, Schallexplosion (Stille), Fledermausschwärme -> Fernkampf verteilt, Fledermäuse töten."] = "- Fase 1 (forma di pipistrello): carica, Esplosione Sonora (silenzio), sciami di pipistrelli -> ranged sparsi, uccidere i pipistrelli."
L["- Phase 2 (50 %): Trollform, Große Heilung -> unterbrechen!"] = "- Fase 2 (50 %): forma di troll, Cura Superiore -> kickare!"
L["- Gedankenschinden/Schattenwort: Schmerz: Schattenschaden -> bannen, heilen."] = "- Flagello Mentale/Parola d'Ombra: Dolore: danno d'ombra -> dispellare, curare."
L["- Feuer-Fledermäuse: werfen Feuerbomben -> aus den Flammen laufen."] = "- Pipistrelli di fuoco: lanciano bombe incendiarie -> uscire dalle fiamme."
L["Taktik: Tank hält Jeklik, Nahkampf auf Schallexplosion achten. Phase 2: Unterbrecher fest einteilen, aus dem Feuer bleiben."] = "Tattica: Il tank tiene Jeklik, i melee attenti all'Esplosione Sonora. Fase 2: kicker assegnati fissi, stare fuori dal fuoco."
L["JEKLIK: Große Heilung unterbrechen! Raus aus dem Feuer!"] = "JEKLIK: Kickare la Cura Superiore! Fuori dal fuoco!"
L["Fledermäuse töten, Fernkampf verteilt gegen Ansturm."] = "Uccidere i pipistrelli, ranged sparsi contro la carica."
L["Hohepriester Venoxis + 4 Schlangen"] = "Sommo Sacerdote Venoxis + 4 serpenti"
L["- Schlangen: vier Adds -> zuerst töten."] = "- Serpenti: quattro add -> uccidere per primi."
L["- Heiliges Feuer/Erneuerung: Priesterform heilt und verursacht Schaden -> unterbrechen und bannen."] = "- Fuoco Sacro/Rinnovamento: la forma di sacerdote cura e fa danno -> kickare e dispellare."
L["- Heiliger Zorn: springt zwischen Spielern -> Abstand halten."] = "- Ira Sacra: rimbalza tra i giocatori -> tenere la distanza."
L["- Schlangenform (50 %): Giftwolken und Gift -> aus Wolken laufen, Gift entfernen."] = "- Forma di serpente (50 %): nubi tossiche e veleno -> uscire dalle nubi, rimuovere il veleno."
L["Taktik: Schlangen zuerst, dann Venoxis mit Unterbrechern. In Schlangenform Giftwolken meiden und Gift entfernen."] = "Tattica: Prima i serpenti, poi Venoxis con i kicker. In forma di serpente evitare le nubi tossiche e rimuovere il veleno."
L["VENOXIS: Schlangen zuerst! Heilige Zauber unterbrechen!"] = "VENOXIS: Prima i serpenti! Kickare gli incantesimi sacri!"
L["Abstand für Heiliger Zorn. Giftwolken meiden."] = "Distanza per l'Ira Sacra. Evitare le nubi tossiche."
L["Venoxis"] = "Venoxis"
L["Totenkopf, Kreuz, Viereck, Mond auf die Schlangen in Tötungsreihenfolge."] = "Teschio, croce, quadrato, luna sui serpenti in ordine di kill."
L["Hohepriesterin Mar'li + Spinnenjunge"] = "Somma Sacerdotessa Mar'li + piccoli di ragno"
L["- Spinnenjunge: wachsen mit der Zeit -> sofort töten."] = "- Piccoli di ragno: crescono col tempo -> uccidere subito."
L["- Giftblitzsalve: Naturschaden im Umkreis -> Gift entfernen."] = "- Raffica di Dardi Velenosi: danno da natura ad area -> rimuovere il veleno."
L["- Spinnenform: umhüllende Netze und Bedrohungsverlust -> zweiter Tank bereit."] = "- Forma di ragno: ragnatele avvolgenti e perdita di aggro -> secondo tank pronto."
L["- Leben entziehen: heilt Mar'li -> bannen bzw. unterbrechen."] = "- Risucchio di Vita: cura Mar'li -> dispellare o kickare."
L["Taktik: Spinnenjunge sofort töten, Gift entfernen. Zwei Tanks wegen Bedrohungsverlust in Spinnenform."] = "Tattica: Uccidere subito i piccoli di ragno, rimuovere il veleno. Due tank per la perdita di aggro in forma di ragno."
L["MAR'LI: Spinnenjunge sofort töten! Gift entfernen!"] = "MAR'LI: Uccidere subito i piccoli di ragno! Rimuovere il veleno!"
L["Zweittank bereit bei Spinnenform."] = "Secondo tank pronto per la forma di ragno."
L["Blutfürst Mandokir + Ohgan"] = "Signore del Sangue Mandokir + Ohgan"
L["- Bedrohlicher Blick: Mandokir starrt einen Spieler an -> dieser macht nichts (kein Angriff, Zauber, Bewegung), sonst Ansturm und Tod."] = "- Sguardo Minaccioso: Mandokir fissa un giocatore -> quel giocatore non fa nulla (niente attacchi, incantesimi, movimenti), altrimenti carica e morte."
L["- Wirbelwind: hoher Schaden im Umkreis -> Nahkampf kurz raus."] = "- Turbine: alto danno ad area -> melee fuori per un attimo."
L["- Geister: tote Spieler können wiederbelebt werden; Mandokir steigt bei Kills im Level -> Tode vermeiden."] = "- Spiriti: i giocatori morti possono essere rianimati; Mandokir sale di livello con le uccisioni -> evitare morti."
L["- Ohgan: Raptor -> von einem zweiten Tank halten."] = "- Ohgan: raptor -> lo tiene un secondo tank."
L["Taktik: Ohgan separat tanken, Mandokir mit Rücken zum Raid. Angestarrte Spieler hören sofort auf zu handeln."] = "Tattica: Tankare Ohgan a parte, Mandokir con la schiena al raid. Chi viene fissato smette subito di agire."
L["MANDOKIR: Angestarrt? NICHTS tun! Wirbelwind -> Nahkampf raus!"] = "MANDOKIR: Fissato? NON fare NIENTE! Turbine -> melee fuori!"
L["Ohgan separat tanken, Tode vermeiden."] = "Tankare Ohgan a parte, evitare morti."
L["Rand des Wahnsinns: Gri'lek, Hazza'rah, Renataki oder Wushoolay"] = "Orlo della Follia: Gri'lek, Hazza'rah, Renataki o Wushoolay"
L["- Wechselnder Boss: einer von vier Bossen, je nach Rotation -> vorher klären, welcher aktiv ist."] = "- Boss a rotazione: uno di quattro boss, secondo la rotazione -> chiarire prima quale è attivo."
L["- Gri'lek: verfolgt Spieler -> Weglaufen; Hazza'rah: Illusionen -> töten; Renataki: Verschwinden/Bedrohungsreset -> Tank bereit."] = "- Gri'lek: insegue i giocatori -> scappare; Hazza'rah: illusioni -> ucciderle; Renataki: Svanire/reset dell'aggro -> tank pronto."
L["- Wushoolay: Kettenblitz -> verteilt stehen."] = "- Wushoolay: Catena di Fulmini -> stare sparsi."
L["Taktik: Je nach Boss Raid verteilen oder Illusionen schnell töten, ansonsten einfacher Tank-und-Schaden-Kampf."] = "Tattica: A seconda del boss sparpagliare il raid o uccidere in fretta le illusioni, per il resto semplice scontro tank e DPS."
L["Optionaler Boss, wird über die Gurubashi-Wahnsinnsmechanik beschworen."] = "Boss opzionale, evocato tramite la meccanica della follia Gurubashi."
L["RAND DES WAHNSINNS: Boss-Mechanik beachten! Verteilt stehen!"] = "ORLO DELLA FOLLIA: Attenzione alla meccanica del boss! Stare sparsi!"
L["Illusionen/Adds schnell töten, Tank bei Bedrohungsreset bereit."] = "Uccidere in fretta illusioni/add, tank pronto al reset dell'aggro."
L["Gahz'ranka"] = "Gahz'ranka"
L["- Frostatem: Frontalkegel mit Manaentzug -> nur Tank vorne."] = "- Soffio di Gelo: cono frontale con drenaggio di mana -> solo il tank davanti."
L["- Gewaltiger Geysir: schleudert Spieler hoch -> Fallschaden, Heiler aufmerksam."] = "- Geyser Imponente: scaraventa in aria i giocatori -> danno da caduta, healer attenti."
L["- Zerschmettern: Rückstoß auf den Tank -> Tank stabil positionieren."] = "- Schianto: respinta sul tank -> posizionare il tank in modo stabile."
L["Taktik: Tank hält Gahz'ranka mit Kopf weg vom Raid, Raid seitlich. Einfacher Kampf, Fallschaden gegenheilen."] = "Tattica: Il tank tiene la testa di Gahz'ranka lontana dal raid, raid sui lati. Scontro semplice, curare il danno da caduta."
L["Optionaler Boss, wird mit einem Schlammstinkerköder am Teich geangelt."] = "Boss opzionale, si pesca allo stagno con un'esca di Mudskunk."
L["GAHZ'RANKA: Nur Tank vorne! Geysir-Fallschaden gegenheilen!"] = "GAHZ'RANKA: Solo il tank davanti! Curare il danno da caduta del geyser!"
L["Raid seitlich, Heiler auf Rückstoß achten."] = "Raid sui lati, healer attenti alla respinta."
L["Hohepriester Thekal + Zelot Lor'Khan und Zelot Zath"] = "Sommo Sacerdote Thekal + Zelota Lor'Khan e Zelota Zath"
L["- Phase 1: Thekal, Lor'Khan und Zath -> alle drei fast gleichzeitig töten, sonst stehen sie wieder auf."] = "- Fase 1: Thekal, Lor'Khan e Zath -> ucciderli tutti e tre quasi insieme, altrimenti si rialzano."
L["- Lor'Khan: heilt -> unterbrechen; Zath: Blenden/Verschwinden -> Tank bereit."] = "- Lor'Khan: cura -> kickare; Zath: Accecamento/Svanire -> tank pronto."
L["- Phase 2 (Tigerform): Kraftschlag mit Rückstoß, Tiger-Adds, Raserei -> Tank an die Wand, Adds töten, Raserei einlullen."] = "- Fase 2 (forma di tigre): Colpo Poderoso con respinta, add tigre, frenesia -> tank al muro, uccidere gli add, frenesia tranquillizzata."
L["Taktik: Drei Tanks, alle drei Ziele gleichmäßig herunterbringen und im Zeitfenster töten. Phase 2: Tank mit Rücken zur Wand."] = "Tattica: Tre tank, abbattere i tre bersagli in modo uniforme e ucciderli nella finestra di tempo. Fase 2: tank con la schiena al muro."
L["THEKAL: Alle drei gleichzeitig töten! Lor'Khan unterbrechen!"] = "THEKAL: Uccidere tutti e tre insieme! Kickare Lor'Khan!"
L["Phase 2: Tiger töten, Raserei einlullen."] = "Fase 2: uccidere le tigri, frenesia tranquillizzata."
L["Thekal"] = "Thekal"
L["Totenkopf Thekal, Kreuz Lor'Khan, Viereck Zath – gleichmäßig herunterbringen."] = "Teschio Thekal, croce Lor'Khan, quadrato Zath – abbatterli in modo uniforme."
L["Hohepriesterin Arlokk + Panther"] = "Somma Sacerdotessa Arlokk + pantere"
L["- Mal der Arlokk: Panther greifen den markierten Spieler an -> Spieler zum Tank laufen, Panther abfangen."] = "- Marchio di Arlokk: le pantere attaccano il giocatore marchiato -> il giocatore corre dal tank, intercettare le pantere."
L["- Verschwinden: Arlokk wird unsichtbar, viele Panther kommen -> Offtanks sammeln, Flächenschaden."] = "- Svanire: Arlokk diventa invisibile, arrivano molte pantere -> gli offtank le raccolgono, AoE."
L["- Solarplexus/Wirbelwind: Tank wird betäubt -> Zweittank bereit."] = "- Colpo allo Stomaco/Turbine: il tank viene stunnato -> secondo tank pronto."
L["Taktik: Raid in der Mitte zusammen, Offtanks fangen Panther ab, Flächenschaden auf Panther. Arlokk nach Erscheinen sofort übernehmen."] = "Tattica: Raid unito al centro, gli offtank intercettano le pantere, AoE sulle pantere. Quando Arlokk riappare riprenderla subito."
L["ARLOKK: Markierter Spieler -> zu den Tanks laufen! Panther sammeln!"] = "ARLOKK: Giocatore marchiato -> correre dai tank! Raccogliere le pantere!"
L["Bei Verschwinden: Flächenschaden auf Panther, Tank bereit."] = "Quando svanisce: AoE sulle pantere, tank pronto."
L["Jin'do der Verhexer + Totems und Skelette"] = "Jin'do il Fattucchiere + totem e scheletri"
L["- Mächtiger Heilungszauberschutz: heilt Jin'do -> sofort zerstören."] = "- Salvaguardia Curativa Potente: cura Jin'do -> distruggerla subito."
L["- Gehirnwäsche-Totem: Gedankenkontrolle -> sofort zerstören."] = "- Totem del Lavaggio del Cervello: controllo mentale -> distruggerlo subito."
L["- Verhexung: Tank verwandelt -> magisch bannen."] = "- Maleficio: il tank viene trasformato -> dispel magico."
L["- Wahnvorstellungen: Fluch, Schatten sehen -> entfluchen, Schatten töten; Teleport in die Grube -> Skelette töten und herauskommen."] = "- Allucinazioni: maledizione, si vedono ombre -> decurse, uccidere le ombre; teletrasporto nella fossa -> uccidere gli scheletri e uscire."
L["Taktik: Fernkampf zerstört sofort alle Totems, Banner/Entflucher fest einteilen. Spieler in der Grube kämpfen sich frei."] = "Tattica: I ranged distruggono subito tutti i totem, dispeller/decurser assegnati fissi. Chi è nella fossa si fa strada combattendo."
L["JIN'DO: Totems sofort zerstören! Verhexung bannen!"] = "JIN'DO: Distruggere subito i totem! Dispellare il Maleficio!"
L["Wahnvorstellungen entfluchen, Schatten töten."] = "Decurse sulle Allucinazioni, uccidere le ombre."
L["Hakkar der Seelenschinder + Söhne des Hakkar"] = "Hakkar lo Scuoianime + Figli di Hakkar"
L["- Blutsauger: regelmäßig Lebensentzug auf den Raid -> vorher Gift (Giftiges Blut) von Söhnen des Hakkar holen, dann schadet er sich selbst."] = "- Risucchio di Sangue: drenaggio di vita regolare sul raid -> prima prendere il veleno (Sangue Velenoso) dai Figli di Hakkar, così si danneggia da solo."
L["- Verderbtes Blut: springt zwischen Spielern -> verteilt stehen."] = "- Sangue Corrotto: salta tra i giocatori -> stare sparsi."
L["- Wahnsinn verursachen: Gedankenkontrolle des Tanks -> Zweittank übernimmt."] = "- Causa Follia: controllo mentale del tank -> il secondo tank lo riprende."
L["- Aspekte: lebende Hohepriester geben Hakkar zusätzliche Fähigkeiten -> vorher alle Priester töten."] = "- Aspetti: i Sommi Sacerdoti vivi danno a Hakkar abilità extra -> uccidere prima tutti i sacerdoti."
L["Taktik: Alle Priester vor Hakkar töten. Vor jedem Blutsauger Söhne töten, damit der Raid vergiftet ist, ansonsten verteilt stehen."] = "Tattica: Uccidere tutti i sacerdoti prima di Hakkar. Prima di ogni Risucchio di Sangue uccidere i Figli così il raid è avvelenato, per il resto stare sparsi."
L["HAKKAR: Vor Blutsauger ins Gift von Sohn des Hakkar!"] = "HAKKAR: Prima del Risucchio di Sangue nel veleno del Figlio di Hakkar!"
L["Verteilt stehen, Zweittank bei Gedankenkontrolle bereit."] = "Stare sparsi, secondo tank pronto per il controllo mentale."
L["Der Schwarze Tempel"] = "Tempio Nero"
L["Oberster Kriegsfürst Naj'entus"] = "High Warlord Naj'entus"
L["- Nadelstachel: Schaden auf zufällige Spieler und Umstehende -> Fernkampf und Heiler verteilt stehen."] = "- Spina Aghiforme: danno su giocatori casuali e su chi è vicino -> ranged e healer sparsi."
L["- Aufspießender Stachel: Spieler wird aufgespießt und erleidet Schaden -> ein anderer Spieler zieht den Stachel per Klick heraus und behält ihn."] = "- Spina Impalante: un giocatore viene impalato e subisce danno -> un altro giocatore estrae la spina con un clic e la tiene."
L["- Gezeitenschild: Boss wird unverwundbar -> mit dem gesammelten Stachel auf den Boss werfen, um den Schild zu brechen."] = "- Scudo della Marea: il boss diventa invulnerabile -> lanciare la spina raccolta sul boss per rompere lo scudo."
L["- Gezeitenschlag beim Brechen des Schilds: Schaden am ganzen Raid -> Raid vorher voll heilen."] = "- Colpo della Marea alla rottura dello scudo: danno su tutto il raid -> prima raid full."
L["- Hartes Enrage nach ca. 8 Min. -> konstanter Schaden nötig."] = "- Enrage rigido dopo circa 8 min. -> serve danno costante."
L["Taktik: Boss in der Mitte tanken, alle anderen verteilt; feste Spieler zum Ziehen der Stacheln und zum Brechen des Schilds einteilen."] = "Tattica: Tankare il boss al centro, tutti gli altri sparsi; assegnare giocatori fissi per estrarre le spine e rompere lo scudo."
L["NAJ'ENTUS: Verteilt stehen! Stacheln sofort ziehen und für den Schild aufheben!"] = "NAJ'ENTUS: Stare sparsi! Estrarre subito le spine e tenerle per lo scudo!"
L["Schild brechen nur mit vollem Leben im Raid."] = "Rompere lo scudo solo con il raid a vita piena."
L["Supremus"] = "Supremus"
L["- Hasserfüllter Stoß (Tankphase): trifft den Nahkämpfer mit der höchsten Bedrohung neben dem Haupttank -> 2-3 Tanks/Spieler mit viel Leben im Nahkampf, Bedrohung aufbauen."] = "- Colpo d'Odio (fase tank): colpisce il melee con l'aggro più alta dopo il main tank -> 2-3 tank/giocatori con molta vita in melee, costruire aggro."
L["- Geschmolzene Flammen/Feuerspur am Boden -> sofort aus dem Feuer gehen."] = "- Fiamme Fuse/scia di fuoco a terra -> uscire subito dal fuoco."
L["- Vulkanausbrüche: Geysire auf dem Boden -> umgehen."] = "- Eruzioni vulcaniche: geyser a terra -> aggirarli."
L["- Jagdphase (wechselt jede Minute): Supremus fixiert einen zufälligen Spieler und wird schneller -> Ziel läuft weg, Raid weicht aus."] = "- Fase caccia (cambia ogni minuto): Supremus fissa un giocatore a caso e diventa più veloce -> il bersaglio scappa, il raid schiva."
L["- Hartes Enrage nach 15 Min."] = "- Enrage rigido dopo 15 min."
L["Taktik: In der Tankphase Haupttank plus Hasserfüllter-Stoß-Abfänger heilen; in der Jagdphase laufen, Feuer meiden und weiter Schaden machen."] = "Tattica: In fase tank curare il main tank e chi assorbe il Colpo d'Odio; in fase caccia correre, evitare il fuoco e continuare a fare danno."
L["SUPREMUS: Jagdphase - Ziel rennt! Aus Feuer und Vulkanen raus!"] = "SUPREMUS: Fase caccia - il bersaglio corre! Fuori da fuoco e vulcani!"
L["Tankphase: Stoß-Abfänger im Nahkampf voll heilen."] = "Fase tank: curare full chi assorbe il colpo in melee."
L["Akamas Schemen"] = "Ombra di Akama"
L["Akamas Schemen + Kanalisierer und Adds der Aschenzungen"] = "Ombra di Akama + canalizzatori e add Linguacenere"
L["- Kanalisierer der Aschenzungen: 6 Adds halten den Schemen gebannt -> alle Kanalisierer töten, dann wird der Schemen angreifbar."] = "- Canalizzatori Linguacenere: 6 add tengono bloccata l'Ombra -> uccidere tutti i canalizzatori, poi l'Ombra diventa attaccabile."
L["- Zauberer der Aschenzungen: kommen aus den Seitentüren und kanalisieren ebenfalls -> sofort töten."] = "- Stregoni Linguacenere: arrivano dalle porte laterali e canalizzano anche loro -> uccidere subito."
L["- Weitere Adds (Verteidiger, Elementaristen, Geistbinder) aus den Seitentüren -> an den Türen abfangen und tanken."] = "- Altri add (difensori, elementalisti, vincolaspiriti) dalle porte laterali -> intercettarli e tankarli alle porte."
L["- Akama darf nicht sterben -> Schemen nach dem Freikommen schnell übernehmen und töten."] = "- Akama non deve morire -> dopo la liberazione prendere subito l'Ombra e ucciderla."
L["Taktik: Zwei Gruppen an den Seitentüren fangen Adds ab, der Rest tötet die Kanalisierer; danach alles auf den Schemen, Akama hilft mit."] = "Tattica: Due gruppi alle porte laterali intercettano gli add, il resto uccide i canalizzatori; poi tutti sull'Ombra, Akama aiuta."
L["SCHEMEN: Kanalisierer und Zauberer zuerst! Türgruppen Adds abfangen!"] = "OMBRA: Prima canalizzatori e stregoni! Gruppi alle porte intercettano gli add!"
L["Akama am Leben halten. Danach alles auf den Schemen."] = "Tenere in vita Akama. Poi tutti sull'Ombra."
L["Teron Blutschatten"] = "Teron Gorefiend"
L["Teron Blutschatten + Schattenhafte Konstrukte"] = "Teron Gorefiend + Costrutti d'Ombra"
L["- Schatten des Todes: Spieler stirbt nach kurzer Zeit und wird zum Geist -> als Geist mit den Geisterfähigkeiten die Konstrukte verlangsamen und töten."] = "- Ombra della Morte: il giocatore muore dopo poco e diventa uno spirito -> da spirito rallentare e uccidere i costrutti con le abilità da spirito."
L["- Schattenhafte Konstrukte: greifen den Raid an -> von Geistern binden, verlangsamen und töten lassen, nicht zum Raid laufen lassen."] = "- Costrutti d'Ombra: attaccano il raid -> farli bloccare, rallentare e uccidere dagli spiriti, non farli arrivare al raid."
L["- Verbrennen: Magie-Debuff mit Feuerschaden -> bannen."] = "- Incenerimento: debuff magico con danno da fuoco -> dispellare."
L["- Zermalmende Schatten: Schattenschaden auf mehrere Spieler -> Heiler reagieren schnell."] = "- Ombre Schiaccianti: danno d'ombra su più giocatori -> healer reattivi."
L["- Schicksalsblüten: schießen Schattenblitze -> Schaden heilen."] = "- Fiori del Destino: sparano Dardi d'Ombra -> curare il danno."
L["Taktik: Teron am Rand tanken; Spieler mit Schatten des Todes stellen sich vor dem Tod an die Konstrukt-Position und erledigen die Adds als Geist."] = "Tattica: Tankare Teron al bordo; chi ha Ombra della Morte si piazza prima di morire alla posizione dei costrutti e li elimina da spirito."
L["TERON: Schatten des Todes - zu den Konstrukten gehen! Als Geist Adds töten!"] = "TERON: Ombra della Morte - andare dai costrutti! Da spirito uccidere gli add!"
L["Verbrennen bannen. Konstrukte vom Raid fernhalten."] = "Dispellare Incenerimento. Tenere i costrutti lontani dal raid."
L["Gurtogg Siedeblut"] = "Gurtogg Bloodboil"
L["- Blutsieden: trifft die 5 entferntesten Spieler, Debuff stapelt -> 3 Fernkampfgruppen im Wechsel hinten stehen."] = "- Sangue Ribollente: colpisce i 5 giocatori più lontani, debuff a stack -> 3 gruppi ranged si alternano dietro."
L["- Teufelssäure / Säurewunde: stapelnde Rüstungsreduktion am Tank -> Tankwechsel."] = "- Acido Vile / Ferita Acida: riduzione armatura a stack sul tank -> cambio tank."
L["- Rauswerfen: Rückstoß mit Bedrohungsverlust -> zweiter Tank sofort übernehmen."] = "- Spinta: respinta con perdita di aggro -> il secondo tank prende subito."
L["- Teufelswut (Phase 2): fixiert einen zufälligen Spieler, der viel Leben und Rüstung bekommt -> diesen Spieler stark heilen, Raid weiter auf Boss."] = "- Furia Vile (fase 2): fissa un giocatore a caso che riceve molta vita e armatura -> curare forte quel giocatore, raid continua sul boss."
L["- Teufelsgeysir: Schaden um den Fixierten -> nicht zu nah stehen."] = "- Geyser Vile: danno intorno al fissato -> non stare troppo vicini."
L["Taktik: Zwei Tanks wechseln wegen der Säure, Fernkampf in Gruppen für Blutsieden rotieren; in Teufelswut den Fixierten hochheilen."] = "Tattica: Due tank si alternano per l'acido, i ranged ruotano in gruppi per Sangue Ribollente; durante Furia Vile curare a fondo il fissato."
L["GURTOGG: Blutsieden-Gruppen rotieren! Tankwechsel bei Säurestapeln!"] = "GURTOGG: Ruotare i gruppi per Sangue Ribollente! Cambio tank sugli stack di acido!"
L["Teufelswut: Fixiertes Ziel voll heilen, nicht wegrennen."] = "Furia Vile: curare full il bersaglio fissato, non scappare."
L["Reliquiar der Seelen"] = "Reliquiario delle Anime"
L["Reliquiar der Seelen (Essenz des Leidens, der Begierde, des Zorns)"] = "Reliquiario delle Anime (Essenza della Sofferenza, del Desiderio, dell'Ira)"
L["- Essenz des Leidens: Aura senkt Heilung massiv, fixiert den nächsten Spieler -> Nahkämpfer mit hohem Leben vorne, schnell töten."] = "- Essenza della Sofferenza: aura che riduce molto le cure, fissa il giocatore più vicino -> melee con molta vita davanti, uccidere in fretta."
L["- Gefangene Seelen zwischen den Phasen: Adds -> schnell töten."] = "- Anime intrappolate tra le fasi: add -> uccidere in fretta."
L["- Essenz der Begierde: Aura reflektiert Schaden auf den Angreifer und senkt Mana -> Schaden dosieren; Runenschild bannen, Abstumpfen und Geistschock unterbrechen."] = "- Essenza del Desiderio: aura che riflette il danno sull'attaccante e riduce il mana -> dosare il danno; dispellare Scudo Runico, kickare Smorzamento e Shock Spirituale."
L["- Essenz des Zorns: Bosheit auf mehrere Spieler -> heilen; Seelenschrei entzieht Mana -> Mana sparen."] = "- Essenza dell'Ira: Malevolenza su più giocatori -> curare; Urlo dell'Anima drena mana -> risparmiare mana."
L["- Zorn steigert sich bei Tankwechsel -> nur einen Tank verwenden."] = "- L'ira aumenta a ogni cambio tank -> usare un solo tank."
L["Taktik: Drei Phasen nacheinander: Leiden schnell töten, Begierde kontrolliert mit Unterbrechern, Zorn mit vollem Raid-Schaden."] = "Tattica: Tre fasi una dopo l'altra: Sofferenza uccisa in fretta, Desiderio controllato con i kicker, Ira con tutto il danno del raid."
L["RELIQUIAR: Phase 2 Reflexion beachten! Unterbrecher bereit!"] = "RELIQUIARIO: Fase 2 attenzione alla riflessione! Kicker pronti!"
L["Phase 1: Wenig Heilung, schnell töten. Adds zwischen den Phasen weg."] = "Fase 1: poche cure, uccidere in fretta. Add tra le fasi via."
L["Mutter Shahraz"] = "Madre Shahraz"
L["- Unheilvoller, Übler, Gemeiner, Sündiger Strahl: Schattenschaden und Debuffs -> Raid mit Schattenwiderstand."] = "- Raggio Sinistro, Vile, Malvagio, Peccaminoso: danno d'ombra e debuff -> raid con resistenza all'ombra."
L["- Tödliche Anziehung: 3 Spieler werden zusammen teleportiert und schaden sich gegenseitig -> sofort auseinander laufen."] = "- Attrazione Fatale: 3 giocatori vengono teletrasportati insieme e si danneggiano a vicenda -> separarsi subito."
L["- Säbelpeitsche: Schaden wird auf Umstehende aufgeteilt -> Nahkampf und Tanks zusammen am Boss."] = "- Sferzata: il danno viene diviso tra chi è vicino -> melee e tank insieme sul boss."
L["- Prismatische Aura: wechselnde Widerstände -> keine Gegenmaßnahme nötig."] = "- Aura Prismatica: resistenze che cambiano -> nessuna contromisura necessaria."
L["- Raserei bei ca. 10% -> Cooldowns aufheben."] = "- Frenesia a circa 10% -> tenere i cooldown."
L["Taktik: Boss mittig tanken, Nahkampf zum Teilen der Säbelpeitsche stapeln, Raid mit Schattenwiderstand-Ausrüstung verteilt."] = "Tattica: Tankare il boss al centro, melee stackati per dividere la Sferzata, raid sparso con equip da resistenza all'ombra."
L["SHAHRAZ: Bei Anziehung SOFORT auseinander laufen!"] = "SHAHRAZ: Con l'Attrazione separarsi SUBITO!"
L["Nahkampf am Boss für Säbelpeitsche. Schattenwiderstand an."] = "Melee sul boss per la Sferzata. Resistenza all'ombra addosso."
L["Rat der Illidari"] = "Consiglio Illidari"
L["Rat der Illidari (Gathios, Malande, Zerevor, Veras)"] = "Consiglio Illidari (Gathios, Malande, Zerevor, Veras)"
L["- Gemeinsamer Lebenspool: alle vier teilen sich das Leben -> Schaden verteilen ist egal, alle sterben zusammen."] = "- Vita condivisa: tutti e quattro condividono la vita -> non conta come si divide il danno, muoiono tutti insieme."
L["- Gathios der Zerschmetterer: Weihe und Segen/Auren -> Segen und Schutz stehlen/reinigen, von Weihe weg tanken."] = "- Gathios lo Spezzatore: Consacrazione e benedizioni/aure -> rubare/purificare benedizioni e protezioni, tankarlo fuori dalla Consacrazione."
L["- Lady Malande: Gebet der Heilung, Göttlicher Zorn, Reflexionsschild -> Heilzauber unterbrechen, Schild beachten."] = "- Lady Malande: Preghiera di Cura, Ira Divina, scudo riflettente -> kickare le cure, attenzione allo scudo."
L["- Hochnethermant Zerevor: Arkane Explosion, Blizzard, Flammenstoß -> auf Distanz halten (Magier/Hexer-Tank), aus Flächenschaden raus."] = "- Gran Negromante del Fato Zerevor: Esplosione Arcana, Blizzard, Colpo di Fiamme -> tenerlo a distanza (tank Mago/Stregone), uscire dall'AoE."
L["- Veras Dunkelschatten: Verschwinden und tödliches Gift -> Gift entfernen, Ziel heilen."] = "- Veras Ombrascura: Svanire e veleno mortale -> rimuovere il veleno, curare il bersaglio."
L["Taktik: Jedes Ratsmitglied eigener Tank an eigener Position, Zerevor auf Distanz; Malandes Heilungen konsequent unterbrechen."] = "Tattica: Ogni membro del consiglio ha il suo tank nella sua posizione, Zerevor a distanza; kickare sempre le cure di Malande."
L["RAT: Malande unterbrechen! Zerevor-AoE meiden!"] = "CONSIGLIO: Kickare Malande! Evitare l'AoE di Zerevor!"
L["Gift von Veras entfernen. Segen von Gathios stehlen/reinigen."] = "Rimuovere il veleno di Veras. Rubare/purificare le benedizioni di Gathios."
L["Rat (Tanks)"] = "Consiglio (tank)"
L["Ein Symbol pro Ratsmitglied für die Tankzuteilung: Totenkopf Gathios, Kreuz Malande, Viereck Zerevor, Mond Veras."] = "Un simbolo per membro del consiglio per l'assegnazione dei tank: teschio Gathios, croce Malande, quadrato Zerevor, luna Veras."
L["Illidan Sturmgrimm"] = "Illidan Grantempesta"
L["Illidan Sturmgrimm + Flammen von Azzinoth und Schattendämonen"] = "Illidan Grantempesta + Fiamme di Azzinoth e Demoni d'Ombra"
L["- Scheren: senkt das max. Leben des Tanks stark -> Tank nutzt Verteidigungs-CDs, Heiler bereit."] = "- Lacerazione: riduce molto la vita massima del tank -> il tank usa i CD difensivi, healer pronti."
L["- Parasitärer Schattenteufel: Spieler bekommt Debuff, Adds schlüpfen -> Adds sofort töten."] = "- Ombravile Parassita: il giocatore riceve un debuff, escono add -> uccidere subito gli add."
L["- Phase 2 (Flammen von Azzinoth): zwei Elementare -> mit Feuerwiderstand-Tanks getrennt tanken, nicht zu nah an die Gleven ziehen."] = "- Fase 2 (Fiamme di Azzinoth): due elementali -> tankarli separati con tank in resistenza al fuoco, non portarli troppo vicino alle glaive."
L["- Augenstrahl / Feuerbälle: Linie aus Feuer am Boden -> ausweichen."] = "- Raggio Oculare / palle di fuoco: linea di fuoco a terra -> schivare."
L["- Dämonenform: Schattendämonen fixieren Spieler -> sofort töten; Fernkampf verteilt (Flammenexplosion)."] = "- Forma demoniaca: i Demoni d'Ombra fissano i giocatori -> uccidere subito; ranged sparsi (Esplosione di Fiamme)."
L["- Maiev (ab ca. 30%): legt Käfigfallen -> Illidan in die Falle ziehen."] = "- Maiev (da circa 30%): piazza trappole gabbia -> portare Illidan nella trappola."
L["Taktik: Phasen 1-5: Tankphase, Flammenphase mit Feuerwiderstands-Tanks, wieder Tank, Dämonenform mit Hexer-Tank, Maiev-Phase mit Fallen."] = "Tattica: Fasi 1-5: fase tank, fase fiamme con tank in resistenza al fuoco, di nuovo tank, forma demoniaca con tank Stregone, fase Maiev con trappole."
L["ILLIDAN: Scheren - Tank-CDs! Schattenteufel und Dämonen sofort töten!"] = "ILLIDAN: Lacerazione - CD del tank! Uccidere subito ombravili e demoni!"
L["Flammen getrennt tanken, Augenstrahl ausweichen. Maiev: Falle nutzen."] = "Tankare le fiamme separate, schivare il Raggio Oculare. Maiev: usare la trappola."
L["Illidan"] = "Illidan"
L["Totenkopf und Kreuz auf die beiden Flammen von Azzinoth (je ein Tank)."] = "Teschio e croce sulle due Fiamme di Azzinoth (un tank ciascuna)."
L["Gruuls Unterschlupf"] = "Antro di Gruul"
L["Hochkönig Maulgar"] = "Re Supremo Maulgar"
L["Hochkönig Maulgar + Krosh, Olm, Kiggler, Blindauge"] = "Re Supremo Maulgar + Krosh, Olm, Kiggler, Occhiocieco"
L["- Blindauge der Seher (Priester): Heilung und Schild -> unterbrechen, als Erstes töten."] = "- Occhiocieco il Veggente (sacerdote): cure e scudo -> kickare, uccidere per primo."
L["- Olm der Beschwörer: beschwört Teufelsjäger -> Hexer tanken/binden, als Zweites töten."] = "- Olm l'Evocatore: evoca Vilsegugi -> gli Stregoni li tankano/bloccano, uccidere per secondo."
L["- Kiggler der Verrückte: Verwandlung und Rückstoß -> auf Distanz von Jägern/Druiden tanken."] = "- Kiggler il Folle: Metamorfosi e respinta -> tankarlo a distanza con Cacciatori/Druidi."
L["- Krosh Feuerhand: starke Feuerzauber -> Magier tankt mit Zauberraub auf Kroshs Zauberschild."] = "- Krosh Manodifuoco: potenti incantesimi di fuoco -> lo tanka un Mago con Furto d'Incantesimo sullo scudo di Krosh."
L["- Maulgar: Wirbelwind und Ansturm, ab 50% Raserei -> Nahkampf bei Wirbelwind raus."] = "- Maulgar: Turbine e carica, dal 50% frenesia -> melee fuori durante il Turbine."
L["Taktik: Jedes Add eigener Tank an eigener Stelle; Reihenfolge Blindauge, Olm, Kiggler, Krosh, zuletzt Maulgar."] = "Tattica: Ogni add ha il suo tank nel suo punto; ordine Occhiocieco, Olm, Kiggler, Krosh, per ultimo Maulgar."
L["MAULGAR: Blindauge zuerst und unterbrechen! Dann Olm, Kiggler, Krosh!"] = "MAULGAR: Prima Occhiocieco e kickarlo! Poi Olm, Kiggler, Krosh!"
L["Krosh nur der Magier-Tank. Wirbelwind: Nahkampf raus."] = "Krosh solo il tank Mago. Turbine: melee fuori."
L["Maulgar"] = "Maulgar"
L["Totenkopf Blindauge, Kreuz Olm, Viereck Kiggler, Mond Krosh, Dreieck Maulgar."] = "Teschio Occhiocieco, croce Olm, quadrato Kiggler, luna Krosh, triangolo Maulgar."
L["Gruul der Drachenschlächter"] = "Gruul the Dragonkiller"
L["- Wachstum: Gruul wird alle 30 Sek. größer und stärker -> weiches Enrage, schnell töten."] = "- Crescita: Gruul diventa più grande e forte ogni 30 sec. -> soft enrage, ucciderlo in fretta."
L["- Verletzender Schlag: trifft den Nahkämpfer mit zweithöchster Bedrohung -> zweiter Tank/Plattenträger direkt hinter dem Haupttank."] = "- Colpo Lacerante: colpisce il melee con la seconda aggro più alta -> secondo tank/portatore di piastre subito dietro il main tank."
L["- Bodenschlag + Zerschmettern: Raid wird herangezogen und versteinert, danach Schaden je nach Nähe -> sofort auseinanderlaufen."] = "- Schianto al Suolo + Frantumazione: il raid viene attirato e pietrificato, poi danno in base alla vicinanza -> separarsi subito."
L["- Höhleneinsturz: Steinschlag am Boden -> sofort raus."] = "- Crollo della Caverna: frana a terra -> uscire subito."
L["- Widerhall: Stille in der Nähe -> Heiler auf Abstand."] = "- Riverbero: silenzio nelle vicinanze -> healer a distanza."
L["Taktik: Fernkampf und Heiler verteilt mit genug Abstand, nach jedem Bodenschlag sofort auseinander; volle Schadensphase gegen das Wachstum."] = "Tattica: Ranged e healer sparsi con abbastanza distanza, dopo ogni Schianto al Suolo separarsi subito; fase di danno pieno contro la Crescita."
L["GRUUL: Nach Bodenschlag SOFORT verteilen! Raus aus dem Einsturz!"] = "GRUUL: Dopo lo Schianto al Suolo sparpagliarsi SUBITO! Fuori dal crollo!"
L["Zweiter Tank für Verletzenden Schlag bereit. Volle DPS gegen Wachstum."] = "Secondo tank pronto per il Colpo Lacerante. DPS pieno contro la Crescita."
L["Hyjalgipfel"] = "Hyjal Summit"
L["Furor Winterfrost"] = "Rage Winterchill"
L["Furor Winterfrost (nach 8 Trash-Wellen)"] = "Rage Winterchill (dopo 8 ondate di trash)"
L["- Tod und Verfall: Schaden in einem Bereich -> sofort herausgehen."] = "- Morte e Decomposizione: danno in un'area -> uscirne subito."
L["- Eisblitz: Frostschaden und Betäubung auf zufälligen Spieler -> heilen."] = "- Dardo di Ghiaccio: danno da gelo e stun su un giocatore a caso -> curare."
L["- Frostnova: friert Spieler in der Nähe fest -> nicht zu viele Spieler eng stehen."] = "- Nova del Gelo: congela i giocatori vicini -> non troppi giocatori stretti."
L["- Frostrüstung: verlangsamt Angreifer -> Nahkampf kurz aushalten."] = "- Armatura del Gelo: rallenta gli attaccanti -> i melee tengono duro per un po'."
L["Taktik: Vorher die Trash-Wellen im Lager abfangen; Boss an Ort und Stelle tanken, Raid aus Tod und Verfall raus."] = "Tattica: Prima intercettare le ondate di trash al campo; tankare il boss sul posto, raid fuori da Morte e Decomposizione."
L["FUROR: Raus aus Tod und Verfall!"] = "WINTERCHILL: Fuori da Morte e Decomposizione!"
L["Eisblitz-Ziele heilen. Trash-Wellen vorher sauber abfangen."] = "Curare i bersagli del Dardo di Ghiaccio. Prima intercettare bene le ondate di trash."
L["Anetheron"] = "Anetheron"
L["Anetheron + Höllenbestien"] = "Anetheron + Infernali"
L["- Aasschwarm: Schaden im Kegel und Heilung reduziert -> Boss vom Raid weggedreht tanken."] = "- Sciame Carogna: danno a cono e cure ridotte -> tankare il boss girato lontano dal raid."
L["- Schlaf: mehrere Spieler schlafen -> Magie bannen."] = "- Sonno: più giocatori dormono -> dispel magico."
L["- Vampiraura: Boss heilt sich bei Treffern -> Tank gut ausgerüstet halten."] = "- Aura Vampirica: il boss si cura quando colpisce -> tank ben equipaggiato."
L["- Inferno: Höllenbestie auf zufälligem Spieler -> von Offtank/Hexer wegtanken, Raid raus aus dem Feuer."] = "- Inferno: Infernale su un giocatore a caso -> offtank/Stregone lo porta via, raid fuori dal fuoco."
L["Taktik: Anetheron vom Raid weg drehen, Höllenbestien von einem Offtank aufnehmen und abseits halten."] = "Tattica: Girare Anetheron lontano dal raid, gli Infernali li prende un offtank e li tiene in disparte."
L["ANETHERON: Höllenbestien sofort abholen! Schlaf bannen!"] = "ANETHERON: Prendere subito gli Infernali! Dispellare il Sonno!"
L["Nicht vor den Boss stellen (Aasschwarm)."] = "Non mettersi davanti al boss (Sciame Carogna)."
L["Kaz'rogal"] = "Kaz'rogal"
L["- Mal von Kaz'rogal: entzieht allen Manaklassen Mana, bei 0 Mana Explosion mit hohem Schaden -> Mana tränken, bei leerem Mana raus aus dem Raid."] = "- Marchio di Kaz'rogal: drena mana a tutte le classi a mana, a 0 mana esplosione con alto danno -> pozioni di mana, a mana vuoto fuori dal raid."
L["- Intervall des Mals wird immer kürzer -> schnell töten."] = "- L'intervallo del marchio si accorcia sempre più -> ucciderlo in fretta."
L["- Kriegsdonner: Betäubung im Nahkampf -> Nahkampf kurz raus wenn möglich."] = "- Tuono di Guerra: stun in melee -> melee fuori per un attimo se possibile."
L["- Spalten: Frontalschaden -> Boss weg vom Raid drehen."] = "- Fendente: danno frontale -> girare il boss lontano dal raid."
L["Taktik: Boss weg vom Raid tanken; Manaklassen achten auf ihr Mana und laufen bei fast leerem Mana vom Raid weg."] = "Tattica: Tankare il boss lontano dal raid; le classi a mana controllano il loro mana e si allontanano dal raid quando è quasi finito."
L["KAZ'ROGAL: Mana im Blick! Fast leer = weg vom Raid laufen!"] = "KAZ'ROGAL: Occhio al mana! Quasi vuoto = lontano dal raid!"
L["Mana-Tränke nutzen. Boss weg vom Raid gedreht."] = "Usare le pozioni di mana. Boss girato lontano dal raid."
L["Azgalor"] = "Azgalor"
L["Azgalor + Geringe Verdammniswachen"] = "Azgalor + Vilguardie Minori"
L["- Feuerregen: Flächenschaden -> sofort raus."] = "- Pioggia di Fuoco: danno ad area -> uscire subito."
L["- Verdammnis: Spieler stirbt nach Ablauf und erzeugt eine Verdammniswache -> zum Offtank laufen, Wache abseits tanken/töten."] = "- Condanna: allo scadere il giocatore muore e genera una Vilguardia -> correre dall'offtank, tankare/uccidere la vilguardia in disparte."
L["- Heulen von Azgalor: Stille im Umkreis -> Heiler auf Abstand."] = "- Ululato di Azgalor: silenzio ad area -> healer a distanza."
L["Taktik: Boss weg vom Raid tanken, Verdammniswachen von Offtank abseits halten und töten; nie im Feuer stehen."] = "Tattica: Tankare il boss lontano dal raid, l'offtank tiene in disparte le vilguardie e le uccide; mai stare nel fuoco."
L["AZGALOR: Raus aus dem Feuerregen! Verdammnis-Ziele zum Offtank!"] = "AZGALOR: Fuori dalla Pioggia di Fuoco! Bersagli della Condanna dall'offtank!"
L["Verdammniswachen abseits tanken. Heiler auf Abstand (Stille)."] = "Tankare le vilguardie in disparte. Healer a distanza (silenzio)."
L["Archimonde"] = "Archimonde"
L["- Luftstoß: schleudert Spieler hoch -> Tränen der Göttin nutzen, um nicht am Sturz zu sterben."] = "- Raffica d'Aria: scaraventa in aria i giocatori -> usare le Lacrime della Dea per non morire per la caduta."
L["- Verdammnisfeuer: Feuerspur folgt Spielern -> wegziehen, nicht durch das Feuer laufen."] = "- Fuoco Funesto: una scia di fuoco segue i giocatori -> portarla via, non attraversare il fuoco."
L["- Furcht: ganzer Raid -> Furchtschutz auf Tank, Totem des Erdstoßes."] = "- Paura: tutto il raid -> Protezione dalla Paura sul tank, Totem del Tremore."
L["- Griff der Legion: Fluch -> entfluchen."] = "- Stretta della Legione: maledizione -> decurse."
L["- Seelenladung bei Spielertoden -> niemand sterben lassen."] = "- Carica d'Anima alla morte dei giocatori -> non far morire nessuno."
L["Taktik: Raid locker verteilt um den Boss, jeder hat Tränen der Göttin in der Leiste; Feuer sofort wegziehen."] = "Tattica: Raid sparso largo intorno al boss, tutti hanno le Lacrime della Dea in barra; portare via subito il fuoco."
L["ARCHIMONDE: Tränen der Göttin bei Luftstoß nutzen!"] = "ARCHIMONDE: Usare le Lacrime della Dea alla Raffica d'Aria!"
L["Verdammnisfeuer wegziehen. Flüche entfernen, Furchtschutz auf Tank."] = "Portare via il Fuoco Funesto. Rimuovere le maledizioni, Protezione dalla Paura sul tank."
L["Karazhan"] = "Karazhan"
L["Attumen der Jäger"] = "Attumen il Cacciatore"
L["Attumen der Jäger + Mittnacht"] = "Attumen il Cacciatore + Mezzanotte"
L["- Mittnacht: zuerst Pferd tanken, Attumen erscheint dazu -> zweiter Tank übernimmt Attumen."] = "- Mezzanotte: prima tankare il cavallo, poi arriva Attumen -> il secondo tank prende Attumen."
L["- Schattenspalten: Frontalschaden -> nur Tank vorne."] = "- Fendente d'Ombra: danno frontale -> solo il tank davanti."
L["- Unkörperliche Präsenz: Fluch -> entfluchen."] = "- Presenza Incorporea: maledizione -> decurse."
L["- Beritten (ab 25%): Ansturm auf entfernte Spieler -> Fernkampf verteilt in mittlerer Distanz."] = "- In sella (dal 25%): carica sui giocatori lontani -> ranged sparsi a media distanza."
L["Taktik: Zwei Tanks: einer auf Mittnacht, einer auf Attumen; nach dem Aufsitzen Ansturm-Schaden heilen und durchziehen."] = "Tattica: Due tank: uno su Mezzanotte, uno su Attumen; dopo che monta in sella curare il danno della carica e andare fino in fondo."
L["ATTUMEN: Nicht vor den Boss! Flüche entfernen!"] = "ATTUMEN: Non davanti al boss! Rimuovere le maledizioni!"
L["Ab Aufsitzen: Fernkampf verteilt für Ansturm."] = "Da quando monta: ranged sparsi per la carica."
L["Moroes"] = "Moroes"
L["Moroes + 4 Gäste"] = "Moroes + 4 ospiti"
L["- Solarplexus: betäubt den Tank -> zweiter Tank mit hoher Bedrohung übernimmt."] = "- Colpo allo Stomaco: stunna il tank -> il secondo tank con aggro alta prende."
L["- Verschwinden + Erdrosseln: stapelnde Blutung auf zufälligem Spieler -> heilen (Eisblock/Gottesschild entfernen)."] = "- Svanire + Garrota: sanguinamento a stack su un giocatore a caso -> curare (rimuovere con Blocco di Ghiaccio/Scudo Divino)."
L["- Gäste: Heiler-Adds (Priester/Paladine) zuerst töten, gefährliche Adds kontrollieren."] = "- Ospiti: uccidere prima gli add healer (sacerdoti/paladini), controllare gli add pericolosi."
L["- Raserei bei 30% -> Gäste vorher töten oder sicher kontrollieren."] = "- Frenesia al 30% -> prima uccidere gli ospiti o tenerli sotto CC sicuro."
L["MOROES: Heiler-Gäste zuerst! CC halten!"] = "MOROES: Prima gli ospiti healer! Tenere i CC!"
L["Solarplexus: Zweiter Tank übernimmt. Erdrosseln-Ziele heilen."] = "Colpo allo Stomaco: prende il secondo tank. Curare i bersagli della Garrota."
L["Totenkopf und Kreuz töten, Viereck und Mond CC, Stern auf Moroes."] = "Teschio e croce da uccidere, quadrato e luna in CC, stella su Moroes."
L["Tugendhafte Maid"] = "Maiden of Virtue"
L["- Buße: lähmt alle Spieler, löst sich bei Schaden -> vorher alle hochheilen."] = "- Penitenza: paralizza tutti i giocatori, si rompe con il danno -> prima curare tutti full."
L["- Heiliges Feuer: Magie-DoT -> bannen."] = "- Fuoco Sacro: DoT magico -> dispellare."
L["- Heiliger Zorn: springt zwischen Spielern -> verteilt stehen."] = "- Ira Sacra: rimbalza tra i giocatori -> stare sparsi."
L["- Geheiligter Boden: Stille um die Maid -> Heiler und Fernkampf außerhalb."] = "- Terreno Consacrato: silenzio intorno alla Maiden -> healer e ranged fuori."
L["Taktik: Fernkampf und Heiler verteilt am Rand des Raums außerhalb des geheiligten Bodens, Nahkampf am Boss."] = "Tattica: Ranged e healer sparsi al bordo della stanza fuori dal terreno consacrato, melee sul boss."
L["MAID: Verteilt am Rand! Vor Buße hochheilen!"] = "MAIDEN: Sparsi al bordo! Curare full prima della Penitenza!"
L["Heiliges Feuer bannen. Heiler nicht in den Geheiligten Boden."] = "Dispellare Fuoco Sacro. Healer non nel Terreno Consacrato."
L["Der große böse Wolf"] = "The Big Bad Wolf"
L["Oper: Der große böse Wolf"] = "Opera: The Big Bad Wolf"
L["- Rotkäppchen: Spieler wird verwandelt, verliert Rüstung und Widerstände -> im Kreis vom Wolf weglaufen."] = "- Cappuccetto Rosso: il giocatore viene trasformato, perde armatura e resistenze -> correre in cerchio lontano dal lupo."
L["- Schreckliches Heulen: Furcht -> Furchtschutz/Erdstoßtotem."] = "- Ululato Terrificante: paura -> Protezione dalla Paura/Totem del Tremore."
L["- Weiter Prankenhieb: Schaden vorne -> nur Tank vor dem Wolf."] = "- Zampata Ampia: danno frontale -> solo il tank davanti al lupo."
L["Taktik: Wolf mittig tanken; Rotkäppchen läuft im Kreis außen herum, Raid bleibt ruhig und macht weiter Schaden."] = "Tattica: Tankare il lupo al centro; Cappuccetto Rosso corre in cerchio all'esterno, il raid resta calmo e continua a fare danno."
L["WOLF: Rotkäppchen im Kreis laufen!"] = "LUPO: Cappuccetto Rosso corre in cerchio!"
L["Nicht vor den Wolf stellen. Furchtschutz auf den Tank."] = "Non mettersi davanti al lupo. Protezione dalla Paura sul tank."
L["Romulo und Julianne"] = "Romulo e Julianne"
L["Oper: Romulo und Julianne"] = "Opera: Romulo e Julianne"
L["- Julianne: Ewige Zuneigung (Heilung) -> unterbrechen; Hingabe-Buff -> reinigen/stehlen."] = "- Julianne: Affetto Eterno (cura) -> kickare; buff Devozione -> purificare/rubare."
L["- Romulo: Wagemut-Buff -> reinigen/stehlen; Gift -> entfernen."] = "- Romulo: buff Audacia -> purificare/rubare; veleno -> rimuovere."
L["- Mächtige Anziehung: Betäubung -> heilen."] = "- Attrazione Potente: stun -> curare."
L["- Phase 3: beide stehen wieder auf und müssen innerhalb von 10 Sek. sterben -> Schaden gleichmäßig verteilen."] = "- Fase 3: entrambi si rialzano e devono morire entro 10 sec. -> distribuire il danno in modo uniforme."
L["Taktik: Erst Julianne, dann Romulo, in Phase 3 beide getrennt tanken und gleichzeitig runterbringen."] = "Tattica: Prima Julianne, poi Romulo, in fase 3 tankarli separati e abbatterli insieme."
L["ROMULO & JULIANNE: Heilung unterbrechen! Phase 3 gleichzeitig töten!"] = "ROMULO E JULIANNE: Kickare le cure! Fase 3 ucciderli insieme!"
L["Buffs reinigen/stehlen. Gift entfernen."] = "Purificare/rubare i buff. Rimuovere il veleno."
L["Totenkopf Julianne, Kreuz Romulo."] = "Teschio Julianne, croce Romulo."
L["Der Zauberer von Oz"] = "Il Mago di Oz"
L["Oper: Der Zauberer von Oz (Dorothee, Tito, Brüller, Strohmann, Blechkopf, Hexe)"] = "Opera: Il Mago di Oz (Dorothee, Tito, Ruggitore, Spaventapasseri, Uomo di Latta, Strega)"
L["- Dorothee: nicht tankbar, Wasserblitze und Furcht, ruft Tito -> Fernkampf zuerst töten."] = "- Dorothee: non tankabile, Dardi d'Acqua e paura, evoca Tito -> i ranged la uccidono per prima."
L["- Brüller: Furcht -> schnell töten."] = "- Ruggitore: paura -> uccidere in fretta."
L["- Strohmann: anfällig für Feuer -> Feuerzauber betäuben ihn, Magier/Hexer übernehmen."] = "- Spaventapasseri: vulnerabile al fuoco -> gli incantesimi di fuoco lo stordiscono, se ne occupano Maghi/Stregoni."
L["- Blechkopf: wird mit der Zeit rostig/langsam -> tanken oder kiten."] = "- Uomo di Latta: col tempo si arrugginisce/rallenta -> tankarlo o kitarlo."
L["- Hexe (am Ende): Wirbelstürme und Kettenblitz -> Wirbelstürmen ausweichen."] = "- Strega (alla fine): tornado e Catena di Fulmini -> schivare i tornado."
L["Taktik: Adds zügig nacheinander töten, Strohmann mit Feuer kontrollieren; danach die Hexe, Wirbelstürme meiden."] = "Tattica: Uccidere gli add in fretta uno dopo l'altro, controllare lo Spaventapasseri con il fuoco; poi la Strega, evitare i tornado."
L["OZ: Dorothee zuerst! Strohmann mit Feuer!"] = "OZ: Prima Dorothee! Spaventapasseri col fuoco!"
L["Hexe: Wirbelstürmen ausweichen."] = "Strega: schivare i tornado."
L["Oz"] = "Oz"
L["Totenkopf Dorothee, Kreuz Brüller, Viereck Strohmann, Mond Blechkopf."] = "Teschio Dorothee, croce Ruggitore, quadrato Spaventapasseri, luna Uomo di Latta."
L["Der Kurator"] = "Il Curatore"
L["Der Kurator + Astrale Blitze"] = "Il Curatore + Lampi Astrali"
L["- Astrale Blitze: alle 10 Sek. ein Add mit Arkanschaden -> sofort töten (Nahkampf)."] = "- Lampi Astrali: ogni 10 sec. un add con danno arcano -> uccidere subito (melee)."
L["- Hasserfüllter Blitz: trifft den Spieler mit dem meisten Leben (außer Tank) -> Spieler mit viel Leben voll heilen."] = "- Lampo d'Odio: colpisce il giocatore con più vita (tranne il tank) -> curare full i giocatori con molta vita."
L["- Hervorrufung: bei 0 Mana erleidet der Kurator +200% Schaden -> alles auf den Boss, Cooldowns nutzen."] = "- Evocazione: a 0 mana il Curatore subisce +200% danni -> tutti sul boss, usare i cooldown."
L["- Enrage bei 15%: keine Blitze mehr, Hasserfüllter Blitz öfter -> durchheilen und schnell töten."] = "- Enrage al 15%: niente più lampi, Lampo d'Odio più spesso -> curare senza sosta e ucciderlo in fretta."
L["Taktik: Fernkampf am Boss, Nahkampf auf die Blitze; in der Hervorrufung volle Cooldowns."] = "Tattica: Ranged sul boss, melee sui lampi; durante l'Evocazione tutti i cooldown."
L["KURATOR: Astrale Blitze sofort töten!"] = "CURATORE: Uccidere subito i Lampi Astrali!"
L["Hervorrufung = alle CDs auf den Boss. Ab 15% durchheilen."] = "Evocazione = tutti i CD sul boss. Dal 15% curare senza sosta."
L["Terestian Siechhuf"] = "Terestian Illhoof"
L["Terestian Siechhuf + Kil'rek"] = "Terestian Illhoof + Kil'rek"
L["- Opferung: Spieler in dämonische Ketten gelegt -> Ketten sofort töten."] = "- Sacrificio: un giocatore viene messo in catene demoniache -> uccidere subito le catene."
L["- Kil'rek (Wichtel): beim Tod erleidet Terestian mehr Schaden -> Kil'rek töten, dann Boss."] = "- Kil'rek (folletto): alla sua morte Terestian subisce più danni -> uccidere Kil'rek, poi il boss."
L["- Dämonische Portale: Wichtel strömen -> per AoE töten."] = "- Portali demoniaci: escono folletti a ondate -> ucciderli ad AoE."
L["- Schattenblitz auf den Tank -> heilen."] = "- Dardo d'Ombra sul tank -> curare."
L["Taktik: Kil'rek zuerst töten, dann auf Terestian; Ketten haben höchste Priorität, Wichtel per AoE."] = "Tattica: Uccidere prima Kil'rek, poi su Terestian; le catene hanno la massima priorità, folletti ad AoE."
L["TERESTIAN: Ketten sofort töten! Kil'rek zuerst!"] = "TERESTIAN: Uccidere subito le catene! Prima Kil'rek!"
L["Wichtel mit AoE wegräumen."] = "Pulire i folletti con l'AoE."
L["Terestian"] = "Terestian"
L["Totenkopf Ketten der Opferung, Kreuz Kil'rek."] = "Teschio Catene del Sacrificio, croce Kil'rek."
L["Arans Schemen"] = "Ombra di Aran"
L["- Flammenkranz: Feuerkreise um Spieler -> nicht bewegen, sonst explodiert der Kreis."] = "- Corona di Fiamme: cerchi di fuoco intorno ai giocatori -> non muoversi, altrimenti il cerchio esplode."
L["- Arkane Explosion: zieht Spieler in die Mitte -> sofort an den Rand laufen."] = "- Esplosione Arcana: attira i giocatori al centro -> correre subito al bordo."
L["- Blizzard: wandert durch den Raum -> rausgehen."] = "- Blizzard: si muove per la stanza -> uscirne."
L["- Arkane/Feuer/Frost-Geschosse -> unterbrechen."] = "- Dardi arcani/di fuoco/di gelo -> kickare."
L["- Wasserelementare bei 40%, Massenverwandlung + Trinken bei 0 Mana -> Elementare verbannen/furchten, beim Trinken volle DPS."] = "- Elementali d'acqua al 40%, Metamorfosi di massa + bere a 0 mana -> esiliare/impaurire gli elementali, mentre beve DPS pieno."
L["Taktik: Raid verteilt am Rand, Unterbrecher fest einteilen; bei Flammenkranz stehenbleiben, bei Arkaner Explosion raus."] = "Tattica: Raid sparso al bordo, kicker assegnati fissi; con la Corona di Fiamme restare fermi, con l'Esplosione Arcana fuori."
L["ARAN: Flammenkranz - NICHT BEWEGEN!"] = "ARAN: Corona di Fiamme - NON MUOVERSI!"
L["Arkane Explosion: an den Rand laufen. Zauber unterbrechen."] = "Esplosione Arcana: correre al bordo. Kickare gli incantesimi."
L["Nethergroll"] = "Netherspite"
L["- Roter Strahl (Beharrlichkeit): Tank stellt sich hinein -> Bedrohung und Leben, Boss greift diesen Spieler an."] = "- Raggio rosso (Perseveranza): il tank ci si mette dentro -> aggro e vita, il boss attacca quel giocatore."
L["- Grüner Strahl (Gelassenheit): Heiler stellt sich hinein -> mehr Heilung, weniger Mana."] = "- Raggio verde (Serenità): un healer ci si mette dentro -> più cure, meno mana."
L["- Blauer Strahl (Dominanz): DPS stellt sich hinein -> mehr Schaden."] = "- Raggio blu (Dominio): un DPS ci si mette dentro -> più danno."
L["- Erschöpfungs-Debuff -> in den Strahlen rotieren."] = "- Debuff di esaurimento -> ruotare nei raggi."
L["- Verbannphase: Netheratem und Leerezonen -> verteilt stehen, Leerezonen meiden."] = "- Fase esilio: Soffio del Vuoto Fatuo e zone del vuoto -> stare sparsi, evitare le zone del vuoto."
L["Taktik: Feste Spieler pro Strahl einteilen und rotieren; in der Verbannphase Abstand halten und Zonen meiden."] = "Tattica: Assegnare giocatori fissi a ogni raggio e ruotare; nella fase esilio tenere la distanza ed evitare le zone."
L["NETHERGROLL: Strahlen blocken und rotieren!"] = "NETHERSPITE: Bloccare i raggi e ruotare!"
L["Verbannphase: Verteilen, aus Leerezonen raus."] = "Fase esilio: sparpagliarsi, fuori dalle zone del vuoto."
L["Schachspiel"] = "Partita a scacchi"
L["Schachspiel (Medivhs Spiel)"] = "Partita a scacchi (la partita di Medivh)"
L["- Spieler steuern Figuren -> den gegnerischen König angreifen."] = "- I giocatori controllano i pezzi -> attaccare il re avversario."
L["- Medivh schummelt: Feuer auf dem Brett und Buffs für Gegner -> Figuren aus dem Feuer ziehen."] = "- Medivh bara: fuoco sulla scacchiera e buff per gli avversari -> spostare i pezzi fuori dal fuoco."
L["- Fähigkeiten der Figuren aktiv nutzen -> König schützen."] = "- Usare attivamente le abilità dei pezzi -> proteggere il re."
L["Taktik: Ein Spieler pro Figur, Fokus auf den gegnerischen König, eigene Figuren aus dem Feuer."] = "Tattica: Un giocatore per pezzo, focus sul re avversario, i propri pezzi fuori dal fuoco."
L["SCHACH: Fokus auf den König! Aus dem Feuer ziehen!"] = "SCACCHI: Focus sul re! Fuori dal fuoco!"
L["Eigenen König schützen."] = "Proteggere il proprio re."
L["Prinz Malchezaar"] = "Principe Malchezaar"
L["Prinz Malchezaar + Höllenbestien"] = "Principe Malchezaar + Infernali"
L["- Entkräften: setzt 5 Spieler auf 1 Leben -> sofort vor der Schattennova weglaufen."] = "- Indebolimento: porta 5 giocatori a 1 di vita -> allontanarsi subito prima della Nova d'Ombra."
L["- Schattennova: Schaden um den Prinzen -> Raid in Abstand halten."] = "- Nova d'Ombra: danno intorno al principe -> raid a distanza."
L["- Höllenbestien: fallen vom Himmel und machen Feuerschaden -> ausweichen."] = "- Infernali: cadono dal cielo e fanno danno da fuoco -> schivarli."
L["- Phase 2 (60%): Äxte, starke Nahkampftreffer -> Tank-CDs."] = "- Fase 2 (60%): asce, colpi melee pesanti -> CD del tank."
L["- Phase 3 (30%): fliegende Äxte und Schadensverstärkung -> Heiler aufmerksam."] = "- Fase 3 (30%): asce volanti e aumento dei danni -> healer attenti."
L["Taktik: Boss in eine Ecke ohne Höllenbestien tanken; Entkräftete laufen sofort raus, ab 30% alles in Schaden."] = "Tattica: Tankare il boss in un angolo senza Infernali; gli indeboliti escono subito, dal 30% tutto nel danno."
L["PRINZ: Entkräftet = sofort raus! Höllenbestien meiden!"] = "PRINCIPE: Indebolito = fuori subito! Evitare gli Infernali!"
L["Phase 2: Tank-CDs. Phase 3: Volle DPS."] = "Fase 2: CD del tank. Fase 3: DPS pieno."
L["Schrecken der Nacht"] = "Nightbane"
L["Schrecken der Nacht + Skelette"] = "Nightbane + scheletri"
L["- Dröhnendes Gebrüll: Furcht -> Furchtschutz/Erdstoßtotem."] = "- Ruggito Rimbombante: paura -> Protezione dalla Paura/Totem del Tremore."
L["- Schwanzfeger/Spalten -> seitlich stehen."] = "- Colpo di Coda/Fendente -> stare sui lati."
L["- Verkohlte Erde: Feuer am Boden -> raus."] = "- Terra Carbonizzata: fuoco a terra -> uscirne."
L["- Luftphase (75/50/25%): Knochenregen ruft Skelette -> sofort töten; Rauchende Explosion auf Tank."] = "- Fase in volo (75/50/25%): Pioggia di Ossa evoca scheletri -> uccidere subito; Esplosione Fumante sul tank."
