L["Ab 25%: Wasserkugeln ausweichen."] = "Dal 25%: schivare i globi d'acqua."
L["Lady Vashj"] = "Lady Vashj"
L["Lady Vashj + Elementare und Schreiter"] = "Lady Vashj + elementali e camminatori"
L["- Phase 1: Schockschlag auf Tank, Statische Aufladung -> verteilt stehen."] = "- Fase 1: Colpo Scioccante sul tank, Carica Statica -> stare sparsi."
L["- Phase 2: Besudelter Kern von besudelten Elementaren -> zu den Generatoren weitergeben."] = "- Fase 2: Nucleo Contaminato dagli elementali contaminati -> passarlo verso i generatori."
