L["BRUTALLUS: Meteorgruppen wechseln! Brand: Abstand halten!"] = "BRUTALLUS: Alternare i gruppi meteora! Bruciatura: tenere la distanza!"
L["6 Min. Enrage - alle Cooldowns nutzen."] = "Enrage a 6 min. - usare tutti i cooldown."
L["Teufelsruch"] = "Felmyst"
L["Teufelsruch + Unnachgiebige Tote"] = "Felmyst + Morti Implacabili"
L["- Einkapseln: Spieler wird angehoben und verursacht Schaden um sich -> sofort von ihm weg."] = "- Incapsulamento: un giocatore viene sollevato e fa danno intorno a sé -> allontanarsi subito da lui."
