L["Adds markieren"] = "Segna gli add"
L["Markiert alle sichtbaren Adds auf einmal nach der Vorlage des Bosses (z. B. Garrs Feuerschwörer, Sulfurons Priester).\nGegner-Namensplaketten müssen an sein (Taste V)."] = "Segna in una volta tutti gli add visibili secondo il modello del boss (es. Giurafuoco di Garr, sacerdoti di Sulfuron).\nLe barre dei nemici devono essere attive (tasto V)."
L["Adds markieren (alle sichtbaren, nach Vorlage)"] = "Segna gli add (tutti i visibili, da modello)"
L["Keine Gegner sichtbar. Namensplaketten der Gegner einschalten (Taste V) und näher an die Adds gehen."] = "Nessun nemico visibile. Attiva le barre dei nemici (tasto V) e avvicinati agli add."
L["%d Gegner markiert (Vorlage: %s)."] = "%d nemici segnati (modello: %s)."
L["Keine passenden Gegner gefunden – schon markiert oder nicht sichtbar."] = "Nessun nemico adatto trovato: già segnati o non visibili."
L["Nur Raidleiter und Co-Raidleiter (Assistenten) können Schlachtzugsymbole setzen."] = "Solo il capoincursione e i suoi assistenti possono mettere i simboli d'incursione."
L["Die Symbolleiste erscheint nur bei ihnen."] = "La barra dei simboli appare solo a loro."
L["Die Abfrage können nur Raidleiter und Co-Raidleiter im Raid starten."] = "Solo il capoincursione e gli assistenti possono avviare la richiesta in incursione."
L["Keine Jäger im Raid."] = "Nessun cacciatore nell'incursione."
L["Frage %d Jäger nach Einlullender Schuss ..."] = "Chiedo a %d cacciatori se hanno Tiro tranquillizzante ..."
L["[RaidMaster] Magmadar: Hast du Einlullender Schuss (Buch aus dem Geschmolzenen Kern)? Bitte mit ja oder nein antworten."] = "[RaidMaster] Magmadar: hai Tiro tranquillizzante (libro del Nucleo Fuso)? Rispondi sì o no."
L["Kein Jäger hat Einlullender Schuss – Raserei mit Heilung und Abstand überstehen."] = "Nessun cacciatore ha Tiro tranquillizzante: superate la Frenesia con cure e distanza."
L["MAGMADAR – Einlull-Rotation: "] = "MAGMADAR – Rotazione tiro tranquillizzante: "
L["[RaidMaster] Einlullender Schuss bei Magmadar: du bist Nr. %d von %d. Bei Raserei sofort schießen, wenn du dran bist."] = "[RaidMaster] Tiro tranquillizzante su Magmadar: sei il n. %d di %d. Spara subito alla Frenesia quando tocca a te."
L["Schlachtzugwarnungen können nur Raidleiter und Co-Raidleiter im Raid senden – nur bei dir angezeigt:"] = "Solo il capoincursione e gli assistenti possono inviare avvisi d'incursione – mostrato solo a te:"
L["Kurzinfo als Raidwarnung"] = "Info breve come avviso d'incursione"
L["Postet die Kurzinfo als Schlachtzugwarnung (nie im normalen Chat)."] = "Pubblica l'info breve come avviso d'incursione (mai nella chat normale)."
L["Jäger abfragen"] = "Chiedi ai cacciatori"
L["Rotation posten"] = "Pubblica rotazione"
L["Fragt alle Jäger im Raid, ob sie Einlullender Schuss haben (mit Addon automatisch, sonst per Flüstern: ja/nein)."] = "Chiede a ogni cacciatore dell'incursione se ha Tiro tranquillizzante (automatico con l'addon, altrimenti via sussurro: sì/no)."
L["Postet die Einlull-Rotation als Schlachtzugwarnung und flüstert jedem Jäger seine Position."] = "Pubblica la rotazione come avviso d'incursione e sussurra a ogni cacciatore la sua posizione."
L["Fenstergröße"] = "Dimensione finestra"
L["Ziehen: Größe ändern – Rechtsklick: Standardgröße"] = "Trascina: ridimensiona – Clic destro: dimensione predefinita"
L["%s ist der feste Raidleiter und wurde zum Raidleiter gemacht."] = "%s è il capoincursione fisso ed è stato nominato capoincursione."
L["Gespeichert – wird beim nächsten Raid übernommen."] = "Salvato – verrà applicato alla prossima incursione."
L["Gespeichert – umstellen kann nur der Raidleiter."] = "Salvato – solo il capoincursione può cambiarlo."
L["Du selbst"] = "Tu stesso"
L["nicht in der Gruppe"] = "non nel gruppo"
L["Plündermeister wählen – als Raidleiter wird die Plündermethode im Spiel sofort umgestellt."] = "Scegli il responsabile del bottino – da capoincursione il metodo di bottino viene cambiato subito nel gioco."
L["Fester Raidleiter"] = "Capoincursione fisso"
L["Dieser Spieler wird automatisch zum Raidleiter gemacht, sobald er in der Gruppe ist, und hat immer alle Rechte im Addon."] = "Questo giocatore viene nominato capoincursione automaticamente appena entra nel gruppo e ha sempre tutti i diritti nell'addon."
L["Festen Raidleiter automatisch zum Raidleiter machen"] = "Nomina automaticamente il capoincursione fisso"
L["Wenn du Gruppenleiter bist und der feste Raidleiter in die Gruppe kommt, übergibt RaidMaster ihm die Leitung."] = "Se sei capogruppo e il capoincursione fisso entra nel gruppo, RaidMaster gli passa il comando."
L["Gespeicherter Plündermeister %s ist nicht im Raid – vorerst bist du Plündermeister."] = "Il responsabile del bottino salvato %s non è nell'incursione – per ora lo sei tu."
L["Plündermeister automatisch gesetzt: %s, Schwelle: %s"] = "Responsabile del bottino impostato automaticamente: %s, soglia: %s"
L["Kein Plündermeister gesetzt!"] = "Nessun responsabile del bottino impostato!"
L["Plündermeister ist %s, gespeichert ist %s."] = "Il responsabile del bottino è %s, salvato: %s."
L["Seltenheitsstufe ist %s, eingestellt ist %s."] = "La soglia del bottino è %s, impostata: %s."
L["Achtung: "] = "Attenzione: "
L["Im Addon ist kein Plündermeister angegeben – es wird der Raidleiter genommen. Auswahl: Loot oder Raidleiter."] = "Nell'addon non è indicato alcun responsabile del bottino – viene usato il capoincursione. Scegli in Bottino o Capoincursione."
L["Empfohlen: Selten (grün) – der Plündermeister verteilt dann schon grüne Items, Kerne und Rezepte sowieso."] = "Consigliato: Non comune (verde) – il responsabile del bottino assegna così anche gli oggetti verdi, nuclei e ricette comunque."
L["Vergessenen Plündermeister automatisch setzen"] = "Imposta automaticamente un responsabile del bottino dimenticato"
L["Als Raidleiter: steht die Plündermethode nicht auf Plündermeister, setzt RaidMaster den gespeicherten Plündermeister und die Schwelle."] = "Da capoincursione: se il metodo di bottino non è responsabile, RaidMaster imposta il responsabile salvato e la soglia."
L["vom Plündermeister %s"] = "dal responsabile del bottino %s"
L["Diese Spielversion hat keinen Plündermeister – Items kommen nicht automatisch in die Warteschlange (Item per Shift-Klick auf der Seite Versteigerung hinzufügen)."] = "Questa versione del gioco non ha responsabile del bottino – gli oggetti non entrano da soli in coda (aggiungi un oggetto con Maiusc-clic nella pagina Asta)."
L["Plündermethode ist nicht Plündermeister – die Items kommen nicht in die Warteschlange. Plündermeister auf der Seite Loot oder Raidleiter setzen."] = "Il metodo di bottino non è responsabile del bottino – gli oggetti non vanno in coda. Imposta il responsabile nella pagina Bottino o Capoincursione."
L["Nur der Plündermeister (%s) stellt die Items in die Warteschlange – öffnet er die Beute, siehst du sie hier auch."] = "Solo il responsabile del bottino (%s) mette gli oggetti in coda – appena apre il bottino li vedi anche qui."
L["Versteigerungen startet nur der Plündermeister (%s)."] = "Solo il responsabile del bottino (%s) avvia le aste."
L["Gesamt %s: |cffff8c1a%d DKP|r · %d Spieler"] = "Totale %s: |cffff8c1a%d DKP|r · %d giocatori"
